-- QoL/QuickBind.lua
L["Not needed right now: shown so you can bind it."] = "Ahora no se necesita: se muestra para que puedas asignarle una tecla."

-- QoL/Buttons.lua
L["Target"] = "Objetivo"
L["Click again for the next name. Drag to move."] = "Haz clic otra vez para el siguiente nombre. Arrastra para mover."
L["Click again for the next name. Shift-drag to move."] = "Haz clic otra vez para el siguiente nombre. Mayús+arrastrar para mover."
L["Press again to delete"] = "Presiona otra vez para eliminar"
L["Bag space"] = "Espacio en las bolsas"
L["Press twice to delete it."] = "Presiona dos veces para eliminarlo."
L["a new icon each press"] = "un icono nuevo con cada pulsación"
L["Marks it with %s."] = "Lo marca con %s."
L["Marks it with %s if it has no icon yet: you don't lead the party."] = "Lo marca con %s si aún no tiene icono: no eres líder del grupo."
L["Marks nothing: in a raid only the leader and assistants set icons."] = "No marca nada: en una banda solo el líder y los ayudantes ponen iconos."
L["Target and wave"] = "Seleccionar y saludar"
L["You can take the quest this item starts. Click to read it."] = "Puedes tomar la misión que inicia este objeto. Haz clic para leerla."

-- QoL/Buy.lua
L["Left %d %s (%s) for you to buy."] = "Quedan %d %s (%s) para que los compres tú."
L["Not enough money to buy %d %s (%s)."] = "No tienes suficiente dinero para comprar %d %s (%s)."
L["Bought %d %s for %s."] = "Compraste %d %s por %s."

-- QoL/Death.lua
L["Run back to your corpse: %s (%s). The Spirit Healer costs %s of resurrection sickness."] = "Vuelve a tu cadáver: %s (%s). El Ángel de la Resurrección cuesta %s de dolencia de resurrección."
L["Run back to your corpse: %s (%s)."] = "Vuelve a tu cadáver: %s (%s)."
L["Resurrect at the Spirit Healer (%s): no resurrection sickness at your level."] = "Resucita con el Ángel de la Resurrección (%s): a tu nivel no hay dolencia de resurrección."
L["Resurrect at the Spirit Healer (%s): your corpse is %s away, longer than %s of sickness."] = "Resucita con el Ángel de la Resurrección (%s): tu cadáver está a %s, más que %s de dolencia."
L["Resurrect at the Spirit Healer (%s)."] = "Resucita con el Ángel de la Resurrección (%s)."
L["Your corpse"] = "Tu cadáver"
L["Spirit Healer"] = "Ángel de la Resurrección"
L["Run back to %s, your corpse is inside: %s (%s)."] = "Vuelve a %s, tu cadáver está dentro: %s (%s)."
L["%s (your corpse is inside)"] = "%s (tu cadáver está dentro)"
L["the dungeon"] = "el calabozo"

-- QoL/Equip.lua
