L["Route: fly to %s."] = "Ruta: vuela a %s."
L["Not enough money to fly to %s: it costs %s."] = "No tienes suficiente dinero para volar a %s: cuesta %s."

-- QoL/Options.lua
L["Off by default: %s does this too."] = "Desactivado por defecto: %s también lo hace."
L["Buttons"] = "Botones"
L["Action buttons"] = "Botones de acción"
L["Quest item button"] = "Botón de objeto de misión"
L["Highlight the step's item in your bags"] = "Resaltar el objeto del paso en tus bolsas"
L["Polestar: step item"] = "Polestar: objeto del paso"
L["A button for the current step's quest item, with count, cooldown and range. Bind it under Key Bindings > AddOns."] = "Un botón para el objeto de misión del paso actual, con cantidad, tiempo de reutilización y alcance. Asígnale una tecla en Atajos > AddOns."
L["Target button"] = "Botón de objetivo"
L["Targets the current step's mobs by name, or the NPCs it sends you to when it has no mob; each click moves to the next name. Bindable."] = "Selecciona por nombre a los monstruos del paso actual, o a los PNJ a los que te envía cuando no tiene monstruos; cada clic pasa al siguiente nombre. Se puede asignar a una tecla."
L["Show who it targets"] = "Mostrar a quién selecciona"
L["The target button's icon shows what you do next: talk, accept, turn in, kill or loot, a skull for an elite, rare or boss, or their face once you have seen them. Their name sits beside it, green for a friendly NPC, red for a mob, gold for an elite or rare, with small icons for the names after it."] = "El icono del botón de objetivo muestra lo que harás a continuación: hablar, aceptar, entregar, matar o despojar, una calavera para un élite, raro o jefe, o su cara una vez que lo hayas visto. Su nombre aparece al lado, en verde para un PNJ amistoso, en rojo para un monstruo y en dorado para un élite o raro, con iconos pequeños para los nombres siguientes."
L["Name new targets in chat"] = "Nombrar los nuevos objetivos en el chat"
L["When the target button's names change, one line in chat lists them (\"Targeting: ...\"). Only you see it."] = "Cuando cambian los nombres del botón de objetivo, una línea en el chat los enumera (\"Objetivo: ...\"). Solo la ves tú."
L["Targeting: %s"] = "Objetivo: %s"
L["Where the target's name shows around the target button: right, left, above or below."] = "Dónde aparece el nombre del objetivo junto al botón de objetivo: derecha, izquierda, arriba o abajo."
L["Right"] = "Derecha"
L["Left"] = "Izquierda"
L["Above"] = "Arriba"
L["Below"] = "Abajo"
L["Reset button positions"] = "Restablecer posición de los botones"
L["Put the buttons back in their default spot."] = "Devuelve los botones a su lugar predeterminado."
L["Quest rewards"] = "Recompensas de misión"
L["Mark quest rewards"] = "Marcar recompensas de misión"
L["On the reward choices, a green arrow marks each upgrade for your spec (with Gear advice on), a thin frame in your accent colour the one to take, and a coin the one that sells for most."] = "Entre las recompensas a elegir, una flecha verde marca cada mejora para tu especialización (con Consejos de equipo activado), un marco fino en tu color de acento la que conviene tomar, y una moneda la que se vende por más."
L["Take the best reward"] = "Tomar la mejor recompensa"
L["Chooses that reward for you when you complete the quest. Hold Shift to choose yourself."] = "Elige esa recompensa por ti al completar la misión. Mantén presionado Mayús para elegir tú."
L["Faster questing"] = "Misiones más rápidas"
L["Instant quest text"] = "Texto de misión instantáneo"
L["Shows quest text at once instead of fading it in (Forever's own option)."] = "Muestra el texto de las misiones de inmediato en vez de hacerlo aparecer poco a poco (opción propia de Forever)."
L["Skip single-option gossip"] = "Omitir diálogos de una sola opción"
L["Faster auto-loot"] = "Despojar automáticamente más rápido"
L["Takes the whole corpse at once when auto-loot is on."] = "Recoge todo el botín del cadáver de una vez cuando Despojar automáticamente está activado."
L["Hide combat errors"] = "Ocultar errores de combate"
L["Hides \"Not enough rage\", \"Out of range\" and cooldown messages. Other errors still show."] = "Oculta los mensajes \"No tienes suficiente ira\", \"Fuera de alcance\" y de tiempo de reutilización. Los demás errores siguen apareciendo."
L["Open the flight map"] = "Abrir el mapa de vuelo"
L["Talking to a flight master opens the map directly. Hold Shift for the gossip."] = "Al hablar con un maestro de vuelo se abre el mapa directamente. Mantén presionado Mayús para ver el diálogo."
L["Mark the route's destination"] = "Marcar el destino de la ruta"
L["Marks where the travel route flies next on the flight map. You still choose the flight."] = "Marca en el mapa de vuelo a dónde vuela después la ruta de viaje. Tú sigues eligiendo el vuelo."
L["Death"] = "Muerte"
L["Corpse or Spirit Healer"] = "Cadáver o Ángel de la Resurrección"
L["As a ghost, points the arrow at the faster way back: your corpse or the nearest Spirit Healer."] = "Como fantasma, apunta la flecha al camino más rápido de vuelta: tu cadáver o el Ángel de la Resurrección más cercano."
L["Release in battlegrounds"] = "Liberar espíritu en campos de batalla"
L["Releases your spirit at once when you die in a battleground, unless you can resurrect yourself or someone offers to. Hold Shift to stay."] = "Libera tu espíritu de inmediato al morir en un campo de batalla, salvo que puedas resucitarte o alguien te lo ofrezca. Mantén presionado Mayús para quedarte."
L["Social"] = "Social"
L["Requests"] = "Solicitudes"
L["Accept summons"] = "Aceptar invocaciones"
L["Takes a summon at once, unless you are in combat. Hold Shift to decide yourself."] = "Acepta una invocación de inmediato, salvo que estés en combate. Mantén presionado Mayús para decidir tú."
L["Accept resurrections"] = "Aceptar resurrecciones"
L["Takes a resurrection as soon as it can, unless the caster is in combat. Never in Hardcore. Hold Shift to decide yourself."] = "Acepta una resurrección en cuanto se puede, salvo que el lanzador esté en combate. Nunca en Extremo. Mantén presionado Mayús para decidir tú."
L["Join friends' parties"] = "Unirse a grupos de amigos"
L["Accepts party invitations from friends, Battle.net friends and your guild, unless joining would leave a queue. Hold Shift to decide yourself."] = "Acepta invitaciones a grupo de amigos, amigos de Battle.net y tu hermandad, salvo que unirte te saque de una cola. Mantén presionado Mayús para decidir tú."
L["Blocking"] = "Bloqueo"
L["Decline other party invitations"] = "Rechazar otras invitaciones a grupo"
L["Declines party invitations from anyone who is not a friend or in your guild."] = "Rechaza invitaciones a grupo de cualquiera que no sea tu amigo ni esté en tu hermandad."
L["Decline guild invitations"] = "Rechazar invitaciones a hermandad"
L["Declines guild invitations, except from friends."] = "Rechaza invitaciones a hermandad, excepto de amigos."
L["Decline duels"] = "Rechazar duelos"
L["Declines duel requests, except from friends and your guild."] = "Rechaza solicitudes de duelo, excepto de amigos y de tu hermandad."
L["Vendors"] = "Mercaderes"
L["Merchants"] = "Mercaderes"
L["Sell grey items"] = "Vender objetos grises"
L["Repair"] = "Reparar"
L["Repairs all gear at merchants who can, when you can afford it. Hold Shift to skip."] = "Repara todo el equipo con los mercaderes que pueden hacerlo, si te alcanza el dinero. Mantén presionado Mayús para omitirlo."
L["Guild bank first"] = "Primero el banco de hermandad"
L["When your guild rank may, the guild bank pays for repairs and your money covers the rest."] = "Si tu rango de hermandad lo permite, el banco de hermandad paga las reparaciones y tu dinero cubre el resto."
L["Experience"] = "Experiencia"
L["XP tracker"] = "Rastreador de PE"
L["XP per hour, time, kills and quests to level, and level splits (/pole xp)."] = "PE por hora, tiempo, muertes y misiones para subir de nivel, y tiempos por nivel (/pole xp)."
L["Reset session"] = "Reiniciar sesión"
L["Start this session's XP per hour from zero."] = "Empieza desde cero los PE por hora de esta sesión."
L["Wear reward upgrades"] = "Equipar mejoras de recompensa"
L["Puts on what a turn-in gives when it is an upgrade for your spec (with Gear advice on), once it reaches your bags and you are out of combat. Hold Shift at the turn-in to skip."] = "Te equipa lo que da una entrega cuando es una mejora para tu especialización (con Consejos de equipo activado), en cuanto llega a tus bolsas y estás fuera de combate. Mantén presionado Mayús al entregar para omitirlo."
L["Buy for the guide"] = "Comprar para la guía"
L["When the step asks you to buy something and the merchant sells it, buys what you still need after selling and repairing. Optional buys and anything over 50g are left to you. Hold Shift to skip."] = "Cuando el paso te pide comprar algo y el mercader lo vende, compra lo que aún te falta después de vender y reparar. Las compras opcionales y todo lo que pase de 50 de oro quedan a tu cargo. Mantén presionado Mayús para omitirlo."
L["Trainers"] = "Instructores"
L["Mark what they target"] = "Marcar lo que seleccionan"
L["A new one each press"] = "Uno nuevo en cada pulsación"
L["Icon on mobs"] = "Icono en monstruos"
L["A new one each press skips the NPCs' icon and leaves a mob that has one as it is."] = "Uno nuevo en cada pulsación omite el icono de los PNJ y deja tal cual a un monstruo que ya tiene uno."
L["Icon on NPCs"] = "Icono en PNJ"
L["A new one each press, so the last few NPCs keep theirs. Every press counts, even one that marks nothing."] = "Uno nuevo en cada pulsación, así que los últimos PNJ conservan el suyo. Cada pulsación cuenta, incluso la que no marca nada."
L["Rare button"] = "Botón de raro"
L["Shows a button that targets a rare Polestar spotted nearby, until it dies or is out of sight. Bindable."] = "Muestra un botón que selecciona a un raro que Polestar detectó cerca, hasta que muere o se pierde de vista. Se le puede asignar una tecla."
L["Guide level on the XP bar"] = "Nivel de la guía en la barra de PE"
L["A mark at the end of the game's XP bar with the level the guide wants you to reach before it moves on, and how many levels away that is when it is more than one."] = "Una marca al final de la barra de PE del juego con el nivel que la guía quiere que alcances antes de continuar, y cuántos niveles faltan cuando es más de uno."
L["Hearthstone"] = "Piedra de hogar"
L["Set your home at the guide's inn"] = "Establecer tu hogar en la posada de la guía"
L["When the step sets your home and you talk to its innkeeper, binds your Hearthstone there. Never at another inn. Hold Shift to skip."] = "Cuando el paso establece tu hogar y hablas con el tabernero, vincula tu Piedra de hogar allí. Nunca en otra posada. Mantén Shift para omitir."
L["Riding reminder"] = "Recordatorio de equitación"
L["At level 40 and 60, if you have not learned riding yet, says the cost in chat (with any Honored discount) and points the arrow at your race's riding trainer when you can afford it. Warlocks and Alliance Paladins are sent to their free-mount quest NPC instead. Once per tier per character."] = "En los niveles 40 y 60, si aún no has aprendido equitación, indica el costo en el chat (con el descuento de Honorable, si lo tienes) y apunta la flecha al instructor de equitación de tu raza cuando puedas pagarlo. A los brujos y a los paladines de la Alianza los envía en su lugar al PNJ de la misión de su montura gratuita. Una vez por rango y por personaje."
L["Hide the game's quest tracker"] = "Ocultar el rastreador de misiones del juego"
L["Hides the game's tracker on the right of the screen, with its quests, achievements and professions, as Questie can. Not with the gamepad interface."] = "Oculta el rastreador del juego a la derecha de la pantalla, con sus misiones, logros y profesiones, como puede hacer Questie. No con la interfaz de control."
L["Reset"] = "Restablecer"
L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator). An item a later step needs gets a lock, so you don't sell it."] = "El objeto que usa el paso actual, o un objeto de misión que recoge, brilla en tus bolsas (y en Baganator). Un objeto que necesita un paso posterior lleva un candado, para que no lo vendas."
L["Offer gear upgrades"] = "Ofrecer mejoras de equipo"
L["When gear from a kill, a chest or a merchant is an upgrade for your spec (with Gear advice on), the guide window offers to put it on. Nothing goes on until you press Wear it; Not this one stops it asking about that item."] = "Cuando el equipo obtenido de un enemigo, un cofre o un mercader es una mejora para tu especialización (con Consejos de equipo activado), la ventana de la guía se ofrece a equiparlo. No se equipa nada hasta que presionas Equiparlo; Este no evita que vuelva a preguntar por ese objeto."
L["Sells Poor-quality items, and anything you marked as junk, when a merchant opens and prints the total. Never an item marked to keep or one a later step needs."] = "Vende los objetos de calidad Pobre y todo lo que marcaste como basura al abrir un mercader, y muestra el total. Nunca un objeto marcado para conservar ni uno que necesite un paso posterior."
L["Restock button"] = "Botón Reabastecer"
L["At a merchant that sells what you are short of, a Restock button under its window buys up to the amounts below (this character's). Nothing is bought until you press it. Other items, such as reagents: /polestar restock <item> <amount>."] = "En un mercader que vende lo que te falta, un botón Reabastecer bajo su ventana compra hasta las cantidades indicadas abajo (las de este personaje). No se compra nada hasta que lo presionas. Otros objetos, como los componentes: /polestar restock <item> <amount>."
L["Keeps this many drinks in your bags. The merchant's best one for your level is bought."] = "Mantiene esta cantidad de bebidas en tus bolsas. Se compra la mejor del mercader para tu nivel."
L["Keeps this much food in your bags. The merchant's best one for your level is bought."] = "Mantiene esta cantidad de comida en tus bolsas. Se compra la mejor del mercader para tu nivel."
L["Keeps this many arrows or shot for the bow, crossbow or gun you wear."] = "Mantiene esta cantidad de flechas o balas para el arco, la ballesta o el arma de fuego que llevas."
L["Bags"] = "Bolsas"
L["When your bags are nearly full, a button shows the free slots and the cheapest junk in them, and while the step collects something the guide window says so too. Press twice to delete that junk: grey items, or common ones you marked as junk. Bindable."] = "Cuando tus bolsas están casi llenas, un botón muestra los espacios libres y la basura más barata que hay en ellas, y mientras el paso recoge algo, la ventana de la guía también lo indica. Presiona dos veces para eliminar esa basura: objetos grises, o comunes que marcaste como basura. Se le puede asignar una tecla."
L["Nearly full at"] = "Casi llenas con"
L["%d slot"] = "%d espacio"
L["%d slots"] = "%d espacios"
L["How many free slots or fewer count as nearly full."] = "Cuántos espacios libres, o menos, cuentan como casi llenas."
L["Junk and keep marks"] = "Marcas de basura y de conservar"
L["Ctrl+Alt-click an item in your bags to mark it as junk, again to keep it, and again to clear it. Junk is sold with the grey items; a kept item is never sold or deleted."] = "Ctrl+Alt+clic en un objeto de tus bolsas para marcarlo como basura, otra vez para conservarlo y otra más para quitar la marca. La basura se vende junto con los objetos grises; un objeto conservado nunca se vende ni se elimina."
L["Step key talks and loots"] = "La tecla del paso habla y despoja"
L["Once the step key has targeted the step's NPC, the next press talks to it; on the corpse of the step's mob, it loots; in the step's quest window, it accepts or completes. Only out of combat, and only on the step the guide is at."] = "Cuando la tecla del paso ya ha seleccionado al PNJ del paso, la siguiente pulsación habla con él; en el cadáver del monstruo del paso, despoja; en la ventana de misión del paso, acepta o completa. Solo fuera de combate y solo en el paso en que está la guía."
L["Warn when out of breath"] = "Avisar al quedarte sin aliento"
L["Under water, a red edge round the screen, a sound and a taskbar flash with 10 seconds of breath left, and again at 4."] = "Bajo el agua, un borde rojo alrededor de la pantalla, un sonido y un parpadeo en la barra de tareas cuando quedan 10 segundos de aliento, y otra vez a los 4."
L["Pick what the step asks for"] = "Elegir lo que pide el paso"
L["At the step's NPC, picks the chat option the guide names, or opens the goods or training the step needs. Only on the step the guide is at. Hold Shift to choose yourself."] = "Con el PNJ del paso, elige la opción de diálogo que indica la guía, o abre la tienda o el entrenamiento que necesita el paso. Solo en el paso en que está la guía. Mantén presionado Mayús para elegir tú."
L["Picks the only option of NPCs without quests. Hold Shift to read it. Off, the game still skips some itself, Pick what the step asks for still picks the step's option, and flight masters follow Open the flight map."] = "Elige la única opción de los PNJ sin misiones. Mantén presionado Mayús para leerla. Desactivado, el juego aún omite algunas por sí mismo, Elegir lo que pide el paso sigue eligiendo la opción del paso y los maestros de vuelo siguen Abrir el mapa de vuelo."
L["Click objectives to target"] = "Clic en los objetivos para seleccionar"
L["Clicking an objective row or NPC heading also targets its NPC outside combat, using the same marking settings as the Target button. This replaces your current target; a failed search clears it."] = "Al hacer clic en una fila de objetivo o en el encabezado de un PNJ, también se selecciona a ese PNJ fuera de combate, con los mismos ajustes de marcado que el botón de objetivo. Esto reemplaza tu objetivo actual; una búsqueda fallida lo quita."
L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Pressing again never takes an icon off. In a party you don't lead, only a unit with no icon gets one; in a raid, only when you lead or assist."] = "El botón de objetivo y la tecla del paso ponen un icono de banda al monstruo y al PNJ que seleccionan; fuera de combate, una pulsación que no encuentra ninguno quita tu objetivo. Volver a pulsar nunca quita un icono. En un grupo que no lideras, solo recibe icono una unidad que no tenga; en una banda, solo si eres líder o ayudante."
L["Ping what they target"] = "Marcar con ping lo que seleccionan"
L["Show quest-starting loot"] = "Mostrar el botín que inicia misiones"
L["When you loot an item that starts a quest you can take, it goes on the quest item button with a glow until you click it or take the quest. The step's own item comes first; several wait their turn, oldest first."] = "Cuando saqueas un objeto que inicia una misión que puedes tomar, pasa al botón de objeto de misión con un brillo hasta que haces clic en él o tomas la misión. El objeto del propio paso va primero; si hay varios, esperan su turno, del más antiguo al más reciente."
L["Track only dungeon quests in dungeons"] = "En calabozos, seguir solo sus misiones"
L["Inside a dungeon or raid, the game's quest tracker and Polestar's quest markers show only that instance's quests. The quests you were tracking come back when you leave, even after a reload inside."] = "Dentro de un calabozo o banda, el rastreador de misiones del juego y los marcadores de misión de Polestar muestran solo las misiones de esa instancia. Las misiones que seguías vuelven al salir, incluso si recargas dentro."
L["New spells at level-up"] = "Hechizos nuevos al subir de nivel"
L["When you level up, a card on the guide window shows the class spells you can now train, what they cost together and the nearest class trainer, with a button for the arrow. Not in combat or instances, and not on levels with nothing new."] = "Al subir de nivel, una tarjeta en la ventana de la guía muestra los hechizos de clase que ya puedes entrenar, cuánto cuestan en total y el instructor de clase más cercano, con un botón para la flecha. No en combate ni en instancias, ni en niveles sin nada nuevo."
L["Old ranks on your bars"] = "Rangos antiguos en tus barras"
L["After training and at login, says which spells on your action bars are a lower rank than the one in your spellbook, with a button that puts the highest rank in the same buttons (out of combat). Macros and items are never touched. Right-click a spell on the card to keep it at its rank; a lower rank you put on a bar yourself is kept too."] = "Después de entrenar y al iniciar sesión, indica qué hechizos de tus barras de acción tienen un rango inferior al de tu libro de hechizos, con un botón que pone el rango más alto en los mismos botones (fuera de combate). Nunca se tocan las macros ni los objetos. Haz clic derecho en un hechizo de la tarjeta para mantenerlo en su rango; un rango inferior que pongas tú en una barra también se mantiene."
L["Forget kept ranks"] = "Olvidar los rangos mantenidos"
L["Lists the spells you kept at a lower rank again."] = "Vuelve a avisar de los hechizos que mantuviste en un rango inferior."
L["Boosted Rest status"] = "Estado de Descanso mejorado"
L["How long the campfire's Boosted Rest lasts and the Cozy Sleeping Bag's cooldown, under the guide window's XP line; your party's Boosted Rest in the party panel."] = "Cuánto dura el Descanso mejorado de la hoguera y el tiempo de reutilización de la Bolsa de dormir acogedora, debajo de la línea de PE de la ventana de la guía; el Descanso mejorado de tu grupo, en el panel del grupo."
L["Take the marked flight"] = "Tomar el vuelo marcado"
L["When the flight map opens, flies to the marked destination. Hold Shift at the flight master to choose yourself."] = "Al abrirse el mapa de vuelo, vuela al destino marcado. Mantén presionado Mayús con el maestro de vuelo para elegir tú."
