L["What Polestar draws on the world map and the minimap. Quest, rare and travel icons start off."] = "Lo que Polestar dibuja en el mapa del mundo y el minimapa. Los iconos de misiones, raros y viajes empiezan desactivados."
L["Guide pins on the world map"] = "Marcadores de guía en el mapa del mundo"
L["Guide pin on the minimap"] = "Marcador de la guía en el minimapa"
L["Trail dots along the travel route"] = "Puntos de rastro en la ruta de viaje"
L["Quest information, rewards and gear advice, and the quest buttons."] = "Información de misiones, recompensas y consejos de equipo, y los botones de misión."
L["Lookup, the dungeon journal and rares: finding things in the world."] = "El Buscador, el diario de calabozos y los raros: encontrar cosas en el mundo."
L["Status"] = "Estado"
L["Actions"] = "Acciones"
L["Start recording"] = "Empezar a grabar"
L["Write quests, routes and world data for guide authors. Off until you start it."] = "Graba misiones, rutas y datos del mundo para autores de guías. Desactivado hasta que lo inicies."
L["Print status"] = "Mostrar estado"
L["The Polestar Recorder addon is not loaded. Enable it in the AddOns list on the character screen to record your play for guide authoring."] = "El AddOn Polestar Recorder no está cargado. Actívalo en la lista de AddOns de la pantalla de selección de personaje para grabar tu partida para crear guías."
L["Recording"] = "Grabando"
L["Stop recording"] = "Detener grabación"
L["Nothing more is written until you start it again."] = "No se graba nada más hasta que lo vuelvas a iniciar."
L["Leveling guides for World of Warcraft: Forever."] = "Guías para subir de nivel en World of Warcraft: Forever."
L["Why Polestar"] = "Por qué Polestar"
L["Leveling guides have become a business: the best routes sit behind subscriptions and paywalls. Polestar goes the other way. It is free, open source under the GPL-3.0, and built by the community that plays it."] = "Las guías para subir de nivel se volvieron un negocio: las mejores rutas están detrás de suscripciones y muros de pago. Polestar va en sentido contrario. Es gratis, de código abierto bajo la GPL-3.0, y lo hace la comunidad que lo juega."
L["Polestar doesn't claim to be the fastest guide, or the smoothest. It is a free alternative, and it gets better with time."] = "Polestar no pretende ser la guía más rápida ni la más pulida. Es una alternativa gratuita, y mejora con el tiempo."
L["Anyone can read the code, fix a step, sharpen a route or write a new guide, and contributions are welcome. The GPL keeps it that way: every copy and every fork stays open."] = "Cualquiera puede leer el código, corregir un paso, afinar una ruta o escribir una guía nueva, y las contribuciones son bienvenidas. La GPL lo mantiene así: cada copia y cada fork sigue siendo abierto."
L["It is young and still in beta, so expect the odd wrong step, waypoint or quest. Every report and every fix tunes it, and together we'll get it where it should be."] = "Es joven y todavía está en beta, así que espera algún paso, punto de ruta o misión equivocados. Cada informe y cada corrección lo afinan, y entre todos lo llevaremos a donde debe estar."
L["Open source and free is the future."] = "El código abierto y gratuito es el futuro."
L["show or hide the guide window"] = "mostrar u ocultar la ventana de la guía"
L["choose a guide"] = "elegir una guía"
L["move through steps"] = "moverse entre pasos"
L["report a problem with a step on the Polestar Discord"] = "informar de un problema con un paso en el Discord de Polestar"
L["every command"] = "todos los comandos"
L["Credits"] = "Créditos"
L["Inter typeface by The Inter Project Authors, SIL Open Font License 1.1."] = "Tipografía Inter de The Inter Project Authors, SIL Open Font License 1.1."
L["Wordmark set in Cinzel by The Cinzel Project Authors, SIL Open Font License 1.1."] = "Logotipo en Cinzel de The Cinzel Project Authors, SIL Open Font License 1.1."
L["Quest and map data includes pfQuest by shagu (MIT License)."] = "Los datos de misiones y mapas incluyen pfQuest de shagu (licencia MIT)."
L["Discord and its logo are trademarks of Discord Inc.; the logo marks the link to the Polestar Discord."] = "Discord y su logotipo son marcas comerciales de Discord Inc.; el logotipo marca el enlace al Discord de Polestar."
L["With EllesmereUI installed, Polestar can follow its accent, font and panel colour through its public skinning API."] = "Con EllesmereUI instalado, Polestar puede seguir su acento, su fuente y su color de panel a través de su API pública de aspecto."
-- L["Gear scores from Forever Leveling BiS by Timearc when it is installed, through its public API."] = ""
L["Maintenance"] = "Mantenimiento"
L["Reset all settings"] = "Restablecer toda la configuración"
L["Every Polestar setting back to default. Progress is kept."] = "Todos los ajustes de Polestar vuelven a su valor predeterminado. El progreso se conserva."
L["Reset positions"] = "Restablecer posiciones"
L["Guide window, arrow and these windows."] = "Ventana de la guía, flecha y estas ventanas."
L["Guides made by other players: switch them on or off, and choose where suggestions come from."] = "Guías hechas por otros jugadores: actívalas o desactívalas, y elige de dónde vienen las sugerencias."
L["The data recorder for guide authors."] = "El grabador de datos para autores de guías."
L["Why Polestar exists, its commands and its credits."] = "Por qué existe Polestar, sus comandos y sus créditos."
L["Nothing to set here yet: the module behind this page is not loaded."] = "Aún no hay nada que configurar aquí: el módulo de esta página no está cargado."
L["No settings match \226\128\156%s\226\128\157."] = "Ningún ajuste coincide con “%s”."
L["1 setting matches"] = "1 ajuste coincide"
L["%d settings match"] = "%d ajustes coinciden"
L["Reset page"] = "Restablecer página"
L["Reload UI"] = "Recargar"
L["Search settings"] = "Buscar ajustes"
L["Open Polestar settings"] = "Abrir la configuración de Polestar"
L["Close the game menu to see Polestar's settings (it cannot be closed for you in combat)."] = "Cierra el menú del juego para ver la configuración de Polestar (en combate no se puede cerrar por ti)."
L["Grow upward"] = "Crecer hacia arriba"
L["Keep the bottom edge in place, so longer steps extend the window up."] = "Mantiene fijo el borde inferior, así los pasos más largos extienden la ventana hacia arriba."
L["Expand step tips"] = "Expandir consejos de los pasos"
L["Start each step with its tip in full instead of one line."] = "Mostrar el consejo de cada paso completo en vez de en una línea."
L["Walk real paths"] = "Seguir caminos reales"
L["The arrow follows paths on the ground around cliffs, water and walls, on Polestar's walking maps, with Shortest Path Forever's router by Cillian Berragan. Off: it points straight at each stop."] = "La flecha sigue caminos por el suelo rodeando acantilados, agua y muros, con los mapas de caminos de Polestar y el enrutador de Shortest Path Forever de Cillian Berragan. Desactivado: apunta directamente a cada parada."
L["Route lines"] = "Líneas de ruta"
L["Class teleports"] = "Teletransportes de clase"
L["Routes may start with a Teleport spell you know (a mage's city teleports, a druid's Moonglade) when it is faster. A city teleport needs a Rune of Teleportation in your bags."] = "Las rutas pueden empezar con un hechizo de teletransporte que conozcas (los de ciudad del mago, el Claro de la Luna del druida) cuando es más rápido. Un teletransporte a ciudad requiere una runa de teletransporte en tus bolsas."
L["Share boat times"] = "Compartir horarios de barcos"
L["Riding a boat, zeppelin, tram or lift times it; your guild and group get those times and you get theirs, so the arrow can say when the next one leaves."] = "Al viajar en barco, zepelín, tranvía o ascensor se mide su horario; tu hermandad y tu grupo reciben esos horarios y tú los suyos, para que la flecha diga cuándo sale el próximo."
L["Warn about missable quests"] = "Avisar de misiones perdibles"
L["Before you take a quest that closes another for good, says which in chat and leaves the accept to you."] = "Antes de aceptar una misión que bloquea otra para siempre, te avisa en el chat y deja que decidas si aceptarla."
L["The arrow's target, the stops of its travel route, the step's other goals, the areas their mobs and objects spawn in, and the route lines."] = "El objetivo de la flecha, las paradas de su ruta de viaje, los otros objetivos del paso, las zonas donde aparecen sus enemigos y objetos, y las líneas de ruta."
L["The arrow's target, the areas it spawns in, and the route line."] = "El objetivo de la flecha, las zonas donde aparece y la línea de ruta."
L["Moving dots from you to the target on the world map and the minimap, along the travel route, while route lines are off."] = "Puntos en movimiento desde ti hasta el objetivo en el mapa del mundo y el minimapa, por la ruta de viaje, mientras las líneas de ruta están desactivadas."
L["Talents"] = "Talentos"
L["Talent plan"] = "Plan de talentos"
L["This translation was made with AI. Help improve it on Discord."] = "Esta traducción se hizo con IA. Ayuda a mejorarla en Discord."
L["Close the game menu to see Polestar's settings."] = "Cierra el menú del juego para ver la configuración de Polestar."
L["Integrations"] = "Integraciones"
L["Settings for other addons Polestar works with, shown when they are installed."] = "Ajustes para otros addons con los que funciona Polestar; se muestran cuando están instalados."
L["None of the addons Polestar works with is installed."] = "No está instalado ninguno de los addons con los que funciona Polestar."
L["The skin's font (the default: the game's own, Fira Sans in Halo), or a font of your choice."] = "La fuente del tema (por defecto: la del juego, Fira Sans en Halo) o una fuente de tu elección."
L["The skin's font"] = "La fuente del tema"
L["Skin"] = "Tema"
L["The skin's arrow"] = "La flecha del tema"
L["Lock arrow and buttons"] = "Bloquear flecha y botones"
L["Stops stray drags on the arrow, the action buttons and the flight and instance timers. Shift-drag still moves them."] = "Evita arrastres accidentales de la flecha, los botones de acción y los temporizadores de vuelo y de estancias. Con Mayús+arrastrar aún se pueden mover."
L["Line style"] = "Estilo de línea"
L["Bar at the bottom"] = "Barra abajo"
L["With Grow upward, put the tabs and the step bar at the bottom edge, next to where the window is pinned."] = "Con Crecer hacia arriba, coloca las pestañas y la barra de pasos en el borde inferior, junto a donde está anclada la ventana."
L["Close offers the guide skips"] = "Cerrar ofertas que la guía omite"
L["After Polestar accepts or turns in a quest, closes the quest window the NPC opens next when the guide skips its quests. Hold Shift to keep it open."] = "Cuando Polestar acepta o entrega una misión, cierra la ventana de misión que el PNJ abre a continuación cuando la guía omite sus misiones. Mantén Shift para dejarla abierta."
L["Elite and escort quests the guides mark for a group. Ask at each, or answer them all: with a group (a party levelling together) or skip them (solo). Discovery, Group quests changes one."] = "Misiones de élite y de escolta que las guías marcan para grupo. Pregunta en cada una, o responde por todas a la vez: hacerlas en grupo (varios jugadores que suben de nivel juntos) u omitirlas (en solitario). Descubrimiento, Misiones de grupo cambia solo una."
L["Ask me at each"] = "Preguntarme en cada una"
L["Do them with a group"] = "Hacerlas en grupo"
L["Skip them"] = "Omitirlas"
L["Offer class quests"] = "Ofrecer misiones de clase"
L["When one of your class's Class guides opens (your level, its first quest), the guide window offers to open it in a tab."] = "Cuando una de las guías de Clase de tu clase queda disponible (tu nivel, su primera misión), la ventana de la guía ofrece abrirla en una pestaña."
L["Celebrating the supporters, contributors and bug reporters behind Polestar."] = "Un homenaje a quienes apoyan Polestar, contribuyen a él y reportan errores."
L["Position trails, marks and the list of spots to walk, in a small window."] = "Rastros de posición, marcas y la lista de puntos que recorrer, en una ventana pequeña."
L["Reset guide progress?"] = "¿Reiniciar progreso de la guía?"
L["Reset progress"] = "Reiniciar progreso"
L["Reset all settings?"] = "¿Restablecer toda la configuración?"
L["Reset all"] = "Restablecer todo"
L["Live"] = "En vivo"
L["Rot Hide Mongrel"] = "Chucho Piel Podrida"
L["Run"] = "Ejecutar"
L["Reset this page?"] = "¿Restablecer esta página?"
L["Every setting on %s goes back to its default."] = "Todos los ajustes de %s vuelven a su valor predeterminado."
L["Waiting to upload"] = "Pendientes de subir"
L["Chunks the Polestar Uploader has not sent yet."] = "Fragmentos que el Polestar Uploader aún no ha enviado."
L["Stored"] = "Almacenado"
L["Last uploaded chunk"] = "Último fragmento subido"
L["Recordings"] = "Grabaciones"
L["Chunks waiting, the last upload and the install id, in chat."] = "Fragmentos pendientes, la última subida y el ID de instalación, en el chat."
L["Characters"] = "Personajes"
L["Icon pack"] = "Paquete de iconos"
L["The medallion under every mark on the world map and the minimap. The skin's: Polestar's, Halo's, or Hearth's for Hearth and the game's own looks. Glyphs only: no medallion."] = "El medallón bajo cada marca del mapa del mundo y del minimapa. El del tema: el de Polestar, el de Halo, o el de Hogar para Hogar y los aspectos propios del juego. Solo glifos: sin medallón."
L["The skin's icons"] = "Los iconos del tema"
L["Glyphs only"] = "Solo glifos"
L["Use deathskips"] = "Usar deathskips"
L["Where dying on purpose and taking the Spirit Healer's resurrection gets you there sooner, the guide shows a step for it. It costs durability and, from level 11, resurrection sickness. Always off on Hardcore characters."] = "Cuando morir a propósito y aceptar la resurrección del Ángel de la Resurrección te lleva antes a tu destino, la guía muestra un paso para ello. Cuesta durabilidad y, desde el nivel 11, dolencia de resurrección. Siempre desactivado en personajes de Extremo."
L["Text size"] = "Tamaño del texto"
L["The size of Polestar's text, apart from the window scale. Changes at once. Right-click to reset."] = "El tamaño del texto de Polestar, aparte de la escala de la ventana. Cambia de inmediato. Clic derecho para restablecer."
L["Numbered pins for the steps ahead"] = "Marcadores numerados para los pasos siguientes"
L["A small pin with its step number where each of the next steps takes you, fainter the further ahead. As many as Up next shows, else five."] = "Un pequeño marcador con su número de paso donde te lleva cada uno de los pasos siguientes, más tenue cuanto más adelante. Tantos como muestre A continuación; si no, cinco."
L["When a leveling guide ends"] = "Al terminar una guía para subir de nivel"
L["Ask me: a window says the guide is done and offers the next one. Continue automatically: the next guide loads in the same tab."] = "Preguntarme: una ventana avisa que la guía terminó y ofrece la siguiente. Continuar automáticamente: la siguiente guía se carga en la misma pestaña."
L["Ask me"] = "Preguntarme"
L["Continue automatically"] = "Continuar automáticamente"
L["%d KiB"] = "%d KiB"
L["%.1f MB"] = "%.1f MB"
L["%d KB"] = "%d KB"
L["Show the whole step"] = "Mostrar el paso completo"
L["Every goal of the step at once, finished ones kept, instead of one person at a time with the others on one line each."] = "Todos los objetivos del paso a la vez, también los terminados, en vez de una persona a la vez con las demás en una línea cada una."
L["Maximum height"] = "Altura máxima"
L["How tall the window may grow, as a share of the screen. A longer step scrolls."] = "Cuánto puede crecer la ventana, como parte de la pantalla. Un paso más largo se desplaza."
L["Hide the arrow with the guide"] = "Ocultar la flecha con la guía"
L["When the guide window is hidden, hide the arrow too."] = "Cuando la ventana de la guía está oculta, ocultar también la flecha."
L["Small conveniences: questing, travel, invitations, merchants, bags, trackers and the map."] = "Pequeñas comodidades: misiones, viajes, invitaciones, mercaderes, bolsas, rastreadores y el mapa."
L["Did you mean:"] = "Tal vez buscabas:"
L["In dungeons and battlegrounds"] = "En calabozos y campos de batalla"
L["How close"] = "Qué tan cerca"
L["Include nearby hand-ins"] = "Incluir entregas cercanas"
L["Wait for Spoken"] = "Esperar a Spoken"
L["Waits 200 ms before each automatic quest accept, turn-in and reward pick, so Spoken has time to notice the window and read it."] = "Espera 200 ms antes de cada aceptación, entrega y elección de recompensa automáticas de misiones, para que Spoken tenga tiempo de detectar la ventana y leerla."
L["Dynamic Questing"] = "Misiones dinámicas"
L["Sound for a new suggestion"] = "Sonido para una sugerencia nueva"
L["Suggests objectives from later steps when you are near them, from your quest log and what is around you. They show under the step in a \"While you're here\" panel: click one to point the arrow there; right-click to dismiss it around here (dismissed twice, it stays away for the zone)."] = "Sugiere objetivos de pasos posteriores cuando estás cerca de ellos, a partir de tu registro de misiones y de lo que hay a tu alrededor. Aparecen bajo el paso en un panel \"Mientras estás aquí\": haz clic en uno para apuntar la flecha hacia allá; clic derecho para descartarlo por aquí (si lo descartas dos veces, no vuelve a aparecer en toda la zona)."
L["A soft chime for each new suggestion (once when several come together), at the game's sound effects volume."] = "Un suave timbre por cada sugerencia nueva (uno solo cuando llegan varias juntas), al volumen de los efectos de sonido del juego."
L["What's new"] = "Novedades"
L["When you abandon a guide quest"] = "Al abandonar una misión de la guía"
L["Always go back for it"] = "Volver siempre por ella"
L["Always skip it"] = "Omitirla siempre"
L["Ask me: the guide stays on its step, leads you back to the quest giver, and the guide window asks. Or always go back for the quest, or always skip it and the quests that follow from it; chat says which."] = "Preguntarme: la guía se queda en su paso, te lleva de vuelta con quien da la misión y la ventana de la guía pregunta. O volver siempre por la misión, u omitirla siempre junto con las misiones que dependen de ella; el chat indica cuál."
L["Also a quest ready to hand in whose NPC is a little out of your way, when the guide hands it in later."] = "También una misión lista para entregar cuyo PNJ queda un poco fuera de tu camino, cuando la guía la entrega más tarde."
L["Hand-ins: how far out of your way"] = "Entregas: cuánto desviarse"
L["The seconds of extra walking a hand-in may cost, to its NPC and back on your way. One in the town you are in always shows; 0 keeps to those."] = "Los segundos de caminata extra que puede costar una entrega, hasta su PNJ y de vuelta a tu camino. Una en el pueblo donde estás siempre se muestra; 0 se limita a esas."
L["Route line on the minimap"] = "Línea de ruta en el minimapa"
L["The way to the goal on the minimap. Off keeps the guide pin there and the line on the world map. Its colour, opacity and size: the gear beside Guide > Arrow & routes > Route lines."] = "El camino al objetivo en el minimapa. Desactivada, se mantienen allí el marcador de la guía y la línea en el mapa del mundo. Su color, opacidad y tamaño: el engranaje junto a Guía > Flecha y rutas > Líneas de ruta."
L["Show and hide"] = "Mostrar y ocultar"
L["Floating button"] = "Botón flotante"
L["Step key targets their mobs"] = "La tecla del paso selecciona sus monstruos"
L["The step key also targets the mobs of the suggestions, nearest first, after the current step's own. It changes only out of combat."] = "La tecla del paso también selecciona a los monstruos de las sugerencias, el más cercano primero, después de los del paso actual. Solo cambia fuera de combate."
L["Mark quests new in Forever"] = "Marcar misiones nuevas de Forever"
L["A small infinity mark beside the name of a quest Forever added, in the guide, While you're here, the Codex and quest tooltips."] = "Una pequeña marca de infinito junto al nombre de una misión que añadió Forever, en la guía, en Mientras estás aquí, en el Codex y en las descripciones emergentes de misiones."
L["The way to the goal on the world map and the minimap: a line or dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "El camino al objetivo en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o viajas, y los tramos siguientes más tenues. Dibujado como lo dibuja Shortest Path Forever de Cillian Berragan."
L["How the route lines are drawn: one solid line, Polestar's dots, or sparkles that drift along the way to the goal (dots while Reduce motion is on)."] = "Cómo se dibujan las líneas de ruta: con una línea continua, con los puntos de Polestar o con destellos que se desplazan por el camino hacia el objetivo (puntos mientras Reducir movimiento está activado)."
L["A Polestar button in the game menu (Esc) that opens the guide menu."] = "Un botón de Polestar en el menú del juego (Esc) que abre el menú de la guía."
L["Backing"] = "Fondo"
L["Soft"] = "Suave"
L["Dark"] = "Oscuro"
L["With Transparent, the tabs and the step bar stay on screen instead of only under the cursor."] = "Con Transparente, las pestañas y la barra de pasos quedan en pantalla en lugar de aparecer solo bajo el cursor."
L["With Transparent: Soft lays a light shade behind each line of text, Dark a dark backing behind the whole window. Off: the outlined text alone on the world."] = "Con Transparente: Suave pone una sombra ligera detrás de cada línea de texto, Oscuro un fondo oscuro detrás de toda la ventana. Desactivado: solo el texto con contorno sobre el mundo."
L["Tell me when a newer Polestar is out"] = "Avisarme cuando haya un Polestar más reciente"
L["At login, a card on the guide window says a newer Polestar is out and how to update; Got it keeps it away for a day. A line in the guide window stays until you update. Two or more updates behind, both show even with this off (the card at most once a day)."] = "Al iniciar sesión, una tarjeta en la ventana de la guía avisa que hay un Polestar más reciente y cómo actualizar; Entendido la oculta por un día. Una línea en la ventana de la guía permanece hasta que actualices. Con dos o más actualizaciones de atraso, ambas aparecen aunque esto esté desactivado (la tarjeta, a lo sumo una vez al día)."
L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. Guide window in the minimap button's menu, the key binding or /polestar opens it there until you leave."] = "Qué hacen la ventana, sus botones y avisos en calabozos, bandas, campos de batalla y arenas. \"Ventana de la guía\" en el menú del botón del minimapa, la tecla asignada o /polestar la abren allí hasta que salgas."
L["A small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Un pequeño botón de Polestar que puedes poner en cualquier parte de la pantalla. Haz clic para ocultar o mostrar Polestar, clic derecho para un menú, arrastra para moverlo. Se oculta con la ventana en combate y en calabozos cuando están en Ocultar."
L["Hiding Polestar leaves the arrow, its travel button and its arrival sound. This character only."] = "Ocultar Polestar deja la flecha, su botón de viaje y su sonido de llegada. Solo para este personaje."
L["How near the middle of its spawn area you must be for a suggestion to show. It goes again a little further out."] = "Qué tan cerca debes estar del centro de su zona de aparición para que se muestre una sugerencia. Desaparece cuando te alejas un poco más."
L["Flight paths you pass"] = "Rutas de vuelo de paso"
L["Also a friendly flight master near you whose flight path you haven't learned yet. Learning it ticks the guide's later step for it too."] = "También un maestro de vuelo amistoso cerca de ti cuya ruta de vuelo aún no has aprendido. Al aprenderla también se marca el paso posterior de la guía para ella."
L["Detour captions"] = "Avisos de rodeo"
L["Under a walk in the journey, say when it goes round a town of the other faction: \"Detour around Southshore\". It only says so: the route and the arrow stay as they are."] = "Debajo de un tramo a pie del trayecto, indica cuándo rodea un pueblo de la otra facción: \"Rodeo para evitar Costasur\". Solo lo indica: la ruta y la flecha no cambian."
L["Manual check-offs and skips, current guide, from your last quest progress on."] = "Marcas manuales y pasos omitidos, guía actual, a partir de tu último progreso en misiones."
L["Your manual check-offs and skipped steps in %s are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Se borran tus marcas manuales y los pasos omitidos en %s a partir de tu último progreso en misiones. Las misiones que ya hiciste siguen hechas, y la guía se queda donde te ubican."
L["Your manual check-offs and skipped steps in the current guide are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Se borran tus marcas manuales y los pasos omitidos de la guía actual a partir de tu último progreso en misiones. Las misiones que ya hiciste siguen hechas, y la guía se queda donde te ubican."
-- L["Points to the current goal. Its look and colours are on the Arrow page."] = ""
-- L["New"] = ""
