L["No community addons installed."] = "No hay AddOns de la comunidad instalados."
L["Suggestions"] = "Sugerencias"
L["Suggest guides from"] = "Sugerir guías de"
L["Where the guide for your level is suggested from. Polestar's guides fill in where a community addon has none for you."] = "De dónde se sugiere la guía para tu nivel. Las guías de Polestar cubren los niveles para los que un AddOn de la comunidad no tiene guía."
L["About community guides"] = "Acerca de las guías de la comunidad"
L["A community addon is a separate addon with someone else's guides for Polestar. It is not part of Polestar, and its guides are not Polestar's own routes."] = "Un AddOn de la comunidad es un AddOn aparte con guías de otra persona para Polestar. No es parte de Polestar, y sus guías no son rutas propias de Polestar."
L["Get a community addon from wherever its author publishes it and install it like any addon, then restart the game. Its guides appear in the guide menu under Community guides, with the author's name. The switch on its row above turns it on or off."] = "Consigue un AddOn de la comunidad donde lo publique su autor e instálalo como cualquier AddOn; luego reinicia el juego. Sus guías aparecen en el menú de guías, en Guías de la comunidad, con el nombre del autor. El interruptor de su fila, arriba, lo activa o desactiva."
L["Each community addon is made and supported by its author: report its problems to them, not to Polestar. It is an addon like any other, so install community addons from authors you trust."] = "Cada AddOn de la comunidad lo hace y mantiene su autor: infórmale a él de sus problemas, no a Polestar. Es un AddOn como cualquier otro, así que instala AddOns de la comunidad de autores en los que confíes."
L["Anyone can make a community addon with Polestar's own tools."] = "Cualquiera puede crear un AddOn de la comunidad con las herramientas propias de Polestar."
L["Community guides, explained"] = "Guías de la comunidad, explicadas"
L["Installed"] = "Instalados"
L["Read more:"] = "Más información:"
L["Read more: docs/GUIDE_PACKS.md in Polestar's source"] = "Más información: docs/GUIDE_PACKS.md en el código fuente de Polestar"
L["Turn on and reload"] = "Activar y recargar"
L["Polestar Guides is turned off in the AddOns list, so Polestar has no guides to show. Turn it on for all your characters and reload?"] = "Polestar Guides está desactivado en la lista de AddOns, así que Polestar no tiene guías que mostrar. ¿Activarlo para todos tus personajes y recargar?"

