L["1. Press Copy report, then Ctrl+C (Cmd+C on a Mac).\n2. In the Polestar Discord, open #bugs and press New Post. Not in it yet? Get the invite.\n3. Paste the report, give it a short title and post it. A bot files it for the developers and tells you in your thread when it's fixed."] = "1. Presiona Copiar informe y luego Ctrl+C (Cmd+C en Mac).\n2. En el Discord de Polestar, abre #bugs y presiona Nueva publicación. ¿Aún no estás dentro? Usa Conseguir la invitación.\n3. Pega el informe, ponle un título breve y publícalo. Un bot lo registra para los desarrolladores y te avisa en tu hilo cuando esté corregido."
