L["Polestar guides you step by step: who to talk to, what to kill or collect, and where to go."] = "Polestar te guía paso a paso: con quién hablar, qué matar o conseguir y a dónde ir."
L["Accept and turn in guide quests for me"] = "Aceptar y entregar por mí las misiones de la guía"
L["Only quests in the next steps of your open guides. Never picks between rewards. Hold Shift to skip."] = "Solo misiones de los próximos pasos de tus guías abiertas. Nunca elige entre recompensas. Mantén presionado Mayús para omitirlo."
L["Load a guide for me when I log in"] = "Cargar una guía por mí al iniciar sesión"
L["Our routes are still in beta"] = "Nuestras rutas siguen en beta"
L["Join us on Discord"] = "Únete a nosotros en Discord"
L["Choose your first guide"] = "Elige tu primera guía"
L["Polestar has no guide to suggest for where you are."] = "Polestar no tiene ninguna guía que sugerir para donde estás."
L["Beta"] = "Beta"
L["Back"] = "Volver"
L["The guide window"] = "La ventana de la guía"
L["Goals tick off as you play."] = "Los objetivos se marcan solos mientras juegas."
L["The arrow"] = "La flecha"
L["Every guide"] = "Todas las guías"
L["Leveling, professions, reputations, mounts and pets."] = "Subir de nivel, profesiones, reputaciones, monturas y mascotas."
L["Pages"] = "Páginas"
L["The shortest walk. Cuts across fields and goes straight over hills."] = "El camino más corto. Cruza campos y sube derecho por los cerros."
L["Takes roads when they aren't much longer, and goes round steep hills."] = "Toma caminos si no son mucho más largos, y le da la vuelta a los cerros empinados."
L["Stays on roads, even when it's longer. Slower, but easy to follow."] = "Se queda en los caminos aunque sea más largo. Más lenta, pero fácil de seguir."
L["Supplies"] = "Suministros"
L["your next stop"] = "tu siguiente parada"
L["Points the way. The map marks each place."] = "Indica el camino. El mapa marca cada lugar."
L["The background of every Polestar window. It changes as you pick."] = "El fondo de cada ventana de Polestar. Cambia a medida que eliges."
L["%s opens the guide window on the right. The arrow points at your first stop."] = "%s abre la ventana de la guía a la derecha. La flecha apunta a tu primera parada."
L["Played to the end in tests, but not yet by players. If a step is wrong, press %s in the guide window and tell us on Discord."] = "Se recorrió hasta el final en pruebas, pero todavía no la han probado jugadores. Si un paso está mal, presiona %s en la ventana de la guía y avísanos en Discord."
L["Feedback, bug reports and news."] = "Comentarios, informes de errores y novedades."
L["Guides by other players, installed like any addon. They show under Community guides in the guide list."] = "Guías de otros jugadores, que se instalan como cualquier addon. Aparecen en Guías de la comunidad, en la lista de guías."
L["Route line"] = "Línea de ruta"
