L["Party: %s"] = "Grupo: %s"
L["For %s: she still needs %d"] = "Para %s: aún le faltan %d"
L["For %s: he still needs %d"] = "Para %s: aún le faltan %d"
L["For %s: still needs %d"] = "Para %s: aún le faltan %d"
L["Party members who run Polestar see your counts under their quest goals, your step and your level. Hidden addon messages to your party only; nothing goes to chat."] = "Los miembros del grupo que usan Polestar ven tus contadores bajo sus objetivos de misión, tu paso y tu nivel. Mensajes de addon ocultos solo para tu grupo; nada va al chat."
L["Their counts under your quest goals, and who lacks a quest you took, with a Share button."] = "Sus contadores bajo tus objetivos de misión y a quién le falta una misión que aceptaste, con un botón Compartir."
L["Wait for the group"] = "Esperar al grupo"
L["When a party member on your quest still needs an objective you finished, the step and its turn-in wait and the arrow leads to what they need. Members in another zone or offline for 2 minutes don't hold you; the party line offers Go on without them."] = "Si un miembro del grupo en tu misión aún necesita un objetivo que ya terminaste, el paso y su entrega esperan y la flecha lleva a lo que necesita. Los miembros en otra zona o desconectados desde hace 2 minutos no te retienen; la línea del grupo ofrece Seguir sin ellos."
L["Say who still needs quest loot"] = "Indicar quién aún necesita botín de misión"
L["On a loot window or roll, a line under a quest item a party member still needs and you don't. Nothing is passed or said for you."] = "En una ventana de botín o una tirada, una línea bajo un objeto de misión que un miembro del grupo aún necesita y tú no. No se pasa ni se dice nada por ti."
L["Party panel"] = "Panel del grupo"
L["Opens by itself when someone in your party runs Polestar too: each member's level, step and what they still need of yours; click a name to point the arrow at them. Closed, it stays closed; /polestar party opens it again."] = "Se abre sola cuando alguien de tu grupo también usa Polestar: el nivel y el paso de cada miembro y lo que aún necesita de ti; haz clic en un nombre para apuntar la flecha hacia esa persona. Si la cierras, se queda cerrada; /polestar party la vuelve a abrir."
L["Tell my party about objectives and ready quests"] = "Avisar a mi grupo de objetivos y misiones listas para entregar"
L["A party chat line with the quest's link when you finish its objectives, and one when the quest is ready to turn in. Everyone in the party sees it, Polestar or not. Never solo or in a raid."] = "Una línea en el chat de grupo con el enlace de la misión cuando completas sus objetivos, y otra cuando la misión está lista para entregar. Todo el grupo la ve, con o sin Polestar. Nunca en solitario ni en banda."
L["Tell my party when I loot an item that starts a quest"] = "Avisar a mi grupo cuando saquee un objeto que inicia una misión"
L["A party chat line with the item's link and the quest it starts."] = "Una línea en el chat de grupo con el enlace del objeto y la misión que inicia."
L["Show my own lines in my chat too"] = "Mostrar también mis propias líneas en mi chat"
L["Off: your party sees the lines Polestar says for you, and your chat stays clear of them."] = "Desactivado: tu grupo ve las líneas que Polestar dice por ti, y tu chat queda libre de ellas."
L["Hide other players' Polestar lines"] = "Ocultar las líneas de Polestar de otros jugadores"
L["Party members' Polestar lines leave your chat. Shown, they carry Polestar's star."] = "Las líneas de Polestar de los miembros del grupo desaparecen de tu chat. Visibles, llevan la estrella de Polestar."
L["Only when someone in the party doesn't have Polestar"] = "Solo si alguien del grupo no tiene Polestar"
L["Nothing goes to chat while everyone in your party runs Polestar: they see your progress in their guide."] = "No se envía nada al chat mientras todo tu grupo use Polestar: ya ven tu progreso en su guía."
L["%s asks you to sync to their guide."] = "%s te pide sincronizarte con su guía."
L["You'll switch to %s."] = "Cambiarás a %s."
L["Their step: %s"] = "Su paso: %s"
L["You're past their step: your guide stays where you are."] = "Ya pasaste su paso: tu guía se queda donde estás."
L["%s is past these, which you haven't done: %s"] = "%s ya pasó estos, que tú no has hecho: %s"
L["You've done these already, so your guide passes them: %s"] = "Ya hiciste estos, así que tu guía los omite: %s"
L["%s asked you to sync to their guide, but it isn't for your character or your copy lacks their step."] = "%s te pidió sincronizarte con su guía, pero no es para tu personaje o tu copia no tiene su paso."
L["No room for another guide tab: close one, then ask %s again."] = "No hay espacio para otra pestaña de guía: cierra una y vuelve a pedírselo a %s."
L["%s synced to your guide."] = "%s se sincronizó con tu guía."
L["%s declined to sync."] = "%s rechazó sincronizarse."
L["%s can't sync: your guide isn't for their character, or their copy lacks your step."] = "%s no puede sincronizarse: tu guía no es para su personaje, o su copia no tiene tu paso."
L["%s is already on your step."] = "%s ya está en tu paso."
L["No one else in your party has been heard running Polestar yet."] = "Aún no se ha detectado a nadie más de tu grupo usando Polestar."
L["You have no step to sync to: open a guide you haven't finished."] = "No tienes ningún paso con el que sincronizar: abre una guía que no hayas terminado."
L["You asked a moment ago: wait %d seconds."] = "Lo pediste hace un momento: espera %d segundos."
L["The game didn't send it: try again in a moment."] = "El juego no lo envió: inténtalo de nuevo en un momento."
L["Asked your party to sync to your step. Each of them chooses."] = "Le pediste a tu grupo sincronizarse con tu paso. Cada uno decide."
L["%s asked you to sync to their guide; that prompt can't show with the gamepad interface."] = "%s te pidió sincronizarte con su guía; ese aviso no puede mostrarse con la interfaz de control."
L["%s is on Polestar %s: your guides can differ. A newer version is out."] = "%s usa Polestar %s: sus guías y las tuyas pueden ser distintas. Hay una versión más reciente."
L["%s is on Polestar %s: your guides can differ."] = "%s usa Polestar %s: sus guías y las tuyas pueden ser distintas."
L["Party sync is on: you and your party see each other's quest progress. Turn it off in Options."] = "La sincronización de grupo está activada: tú y tu grupo ven el progreso de misiones de los demás. Desactívala en Opciones."
L["Ask other players' Polestar which version it is"] = "Preguntar al Polestar de otros jugadores qué versión es"
L["Up to 10 hidden addon whispers a session, to players of your faction you target or mouse over outside cities, combat and dungeons, and an answer to theirs: only the version number, so Polestar can tell you when a newer one is out. Off: none sent or answered."] = "Hasta 10 susurros ocultos del AddOn por sesión, a jugadores de tu facción que seleccionas o sobre los que pasas el cursor fuera de ciudades, combates y calabozos, y una respuesta a los suyos: solo el número de versión, para que Polestar pueda avisarte cuando haya una más reciente. Desactivado: no se envía ni se responde ninguno."

