-- Talents/Builds.lua
L["Holy"] = "Sagrado"
L["Protection"] = "Protección"
L["Level as Retribution (quickest solo, with a two-hander and Seal of Command) or Protection (safe group pulls, dungeon-tank ready). Holy suits raids; it can level through its melee build, more slowly, if you want to heal dungeons on the way."] = "Sube de nivel como Reprensión (lo más rápido en solitario, con un arma de dos manos y Sello de orden) o Protección (pulls de grupo seguros, listo para tanquear mazmorras). Sagrado va bien para bandas; puede subir de nivel con su build cuerpo a cuerpo, más despacio, si quieres sanar mazmorras por el camino."
L["Start with Divine Intellect: more mana means you can melee and still cover your own (or a group's) healing."] = "Empieza con Intelecto divino: más maná significa que puedes luchar cuerpo a cuerpo y aun así cubrir tu propia sanación (o la de un grupo)."
L["Improved Seals raises every seal and Judgement here, which is where Holy's leveling damage comes from."] = "Sellos mejorados potencia aquí cada sello y Sentencia, que es de donde sale el daño de Sagrado al subir de nivel."
L["Reverence keeps a trickle of regen going while casting; three ranks unlock Illumination."] = "Reverencia mantiene un poco de regeneración mientras lanzas hechizos; tres rangos desbloquean Iluminación."
L["Illumination refunds mana on critical heals and is the heart of Holy's staying power."] = "Iluminación devuelve maná con las sanaciones críticas y es el corazón del aguante de Sagrado."
L["Holy Shock is a talent on Forever: an instant heal or Holy hit, handy for emergencies and for pulling."] = "Choque Sagrado es un talento en Forever: una sanación o golpe Sagrado instantáneo, útil para emergencias y para hacer pull."
L["Holy Power raises Holy Shock's crit chance, feeding Illumination and Infusion of Light."] = "Poder Sagrado aumenta la probabilidad de crítico de Choque Sagrado, alimentando Iluminación e Infusión de luz."
L["Light's Vigil turns Holy Shock into a group-heal burst; this is the signature Forever Holy talent."] = "Vigilia de la Luz convierte Choque Sagrado en una ráfaga de sanación de grupo; es el talento Sagrado distintivo de Forever."
L["The remaining 20 points go to Retribution: cheaper spells and more melee crit while questing, ending in Seal of Command."] = "Los 20 puntos restantes van a Reprensión: hechizos más baratos y más crítico cuerpo a cuerpo al hacer misiones, terminando en Sello de orden."
L["Open with Redoubt: blocking pays off at once, and Shield Specialization needs all five ranks."] = "Empieza con Reducto: bloquear compensa enseguida, y Especialización en escudos necesita los cinco rangos."
L["Precision and Anticipation help you land hits and dodge them while questing with a shield."] = "Precisión y Anticipación te ayudan a acertar y a esquivar mientras haces misiones con escudo."
L["Improved Seal of Fury and Improved Righteous Fury begin the mana and mitigation cycle Forever tanking is built on."] = "Sello de furia mejorado y Furia justa mejorada inician el ciclo de maná y mitigación en el que se basa tanquear en Forever."
L["Around 20 points in, you match the usual dungeon-tank setup: Shield Specialization, Sacred Duty and Swift Judgement are complete."] = "Hacia los 20 puntos alcanzas la configuración habitual de tanque de mazmorras: Especialización en escudos, Deber sagrado y Sentencia rápida están completos."
L["Templar's Bulwark is an absorb cooldown that scales with your health, and Holy Shield later in the plan requires it."] = "Baluarte del templario es un tiempo de reutilización de absorción que escala con tu salud, y Escudo Sagrado lo requiere más adelante en el plan."
L["Iron Creed adds threat and damage reduction to Holy Strike while Righteous Fury is active."] = "Credo de hierro añade amenaza y reducción de daño a Golpe Sagrado mientras Furia justa está activa."
L["Holy Shield is the capstone: more block uptime, with Holy damage each time you block. Ideal for pulling packs."] = "Escudo Sagrado es la culminación: más tiempo de bloqueo, con daño Sagrado cada vez que bloqueas. Ideal para hacer pull a grupos."
L["Leftover points buy armor, a quicker Hammer of Justice, and Holy Strength and seal damage for leveling."] = "Los puntos sobrantes compran armadura, un Martillo de justicia más rápido, y Fuerza Sagrada y daño de sellos para subir de nivel."
L["Benediction lowers the mana cost of Judgement, Holy Strike and seals, so you rest less between fights."] = "Bendición reduce el coste de maná de Sentencia, Golpe Sagrado y los sellos, así descansas menos entre combates."
L["Seal of Command is the main two-hander seal for leveling; take it as soon as it opens."] = "Sello de orden es el sello principal para armas de dos manos al subir de nivel; cógelo en cuanto esté disponible."
L["Sanctified Judgement gives mana back and is the prerequisite arrow for Vengeance."] = "Sentencia santificada devuelve maná y es el requisito (flecha) para Venganza."
L["Sacred Arbiter strengthens Holy Strike and keeps Judgements rolling, and completes the 20 points row 5 asks for."] = "Árbitro sagrado refuerza Golpe Sagrado, mantiene las Sentencias en marcha y completa los 20 puntos que exige la fila 5."
L["Vengeance, then Two-Handed Weapon Specialization: the crit-driven damage core of the two-hander plan."] = "Venganza y luego Especialización en armas de dos manos: el núcleo de daño basado en críticos del plan a dos manos."
L["Pursuit of Justice adds run speed. Champion of the Light is left out while the Retribution Aura spell-power bug keeps spell damage low."] = "Búsqueda de la justicia aumenta la velocidad de carrera. Campeón de la Luz se queda fuera mientras el error de poder con hechizos de Aura de reprensión mantenga bajo el daño de hechizos."
L["Twist of Light makes swapping seals cheaper and adds seal echoes; it is Forever's seal-twisting talent."] = "Giro de Luz abarata el cambio de sellos y añade ecos de sello; es el talento de alternancia de sellos de Forever."
L["Spare points go to Divine Strength and Holy's Improved Seals for damage, then Deflection for survival."] = "Los puntos sobrantes van a Fuerza divina y a Sellos mejorados de Sagrado para daño, y luego a Desviación para sobrevivir."
L["Level as Combat with a sword (Riposte, Blade Flurry, Adrenaline Rush) for the steadiest kills, or Assassination with daggers and poisons (Mutilate). Subtlety's Hemorrhage plan suits stealth openers and is slower solo."] = "Sube de nivel como Combate con espada (Estocada, Torbellino de cuchillas, Ímpetu de adrenalina) para los mejores asesinatos, o Asesinato con dagas y venenos (Mutilar). El plan Hemorragia de Subterfugio es ideal para openers en sigilo y es más lento en solitario."
L["Malice first: crit for every attack and poison, and it opens Lethality."] = "Primero Malicia: crítico para cada ataque y veneno, y abre Letalidad."
L["Ruthlessness gives finishers a chance at a free combo point; Murder adds damage against humanoids and giants."] = "La Crueldad da a los finalizadores la posibilidad de obtener un punto de combo gratis; Asesinato añade daño contra humanoides y gigantes."
L["Relentless Strikes refunds energy from finishers, so fights flow without waiting."] = "Los Golpes implacables reembolsan energía de los finalizadores, así los combates fluyen sin esperas."
L["Improved Poisons puts poisons on more often and makes charges last; take them as soon as you train poisons."] = "Venenos mejorados aplica venenos con más frecuencia y hace que las cargas duren más; tómalos tan pronto como entrenes venenos."
L["Mutilate is Forever's dual-wield dagger strike: two combo points a use, and more damage on poisoned targets."] = "Mutilar es el golpe de daga con doble arma de Forever: dos puntos de combo por uso y más daño en objetivos envenenados."
L["Seal Fate turns crits into extra combo points; with Malice and Lethality it is the core of the build."] = "Sello del destino convierte los críticos en puntos de combo extra; con Malicia y Letalidad es el núcleo del build."
L["Venom is the capstone: a finisher that strengthens your poisons for a while."] = "Veneno es el capstone: un finalizador que fortalece tus venenos por un tiempo."
L["The last 20 points go to Combat: cheaper Sinister Strikes, a stronger Eviscerate, more hit and parry, Riposte and a stronger off-hand."] = "Los últimos 20 puntos van a Combate: Golpes furtivos más baratos, un Destripar más fuerte, más impacto y parada, Estocada y una mano secundaria más fuerte."
L["Improved Sinister Strike first: cheaper Sinister Strikes are the biggest early gain."] = "Primero Golpe furtivo mejorado: los Golpes furtivos más baratos son la mayor ganancia inicial."
L["Precision helps you hit more often; it also opens Dual Wield Specialization."] = "La Precisión te ayuda a golpear con más frecuencia; también abre Especialización en doble arma."
L["Riposte follows each parry with a heavy strike that also disarms."] = "La Estocada sigue cada parada con un golpe pesado que también desarma."
L["Blade Flurry is faster attacks and cleave on demand; Hack and Slash then adds extra attacks with swords and axes."] = "El Torbellino de cuchillas son ataques más rápidos y un golpe en abanico a demanda; Cortar y acuchillar añade ataques extra con espadas y hachas."
L["Adrenaline Rush is the capstone: double energy for 15 seconds, enough for a second mob."] = "El Ímpetu de adrenalina es el capstone: energía doble durante 15 segundos, suficiente para un segundo enemigo."
L["The remaining points go to Assassination for crit, free combo points, energy refunds and Lethality."] = "Los puntos restantes van a Asesinato para críticos, puntos de combo gratis, reembolsos de energía y Letalidad."
L["Opportunity adds damage to Backstab, Ambush and Garrote, your stealth openers."] = "La Oportunidad añade daño a Apuñalar por la espalda, Emboscada y Degüello, tus openers desde el sigilo."
L["Improved Ambush and Initiative make the opener the fight: a likely crit and extra combo points."] = "Emboscada mejorada e Iniciativa hacen del opener el combate: un probable crítico y puntos de combo extra."
L["Serrated Blades ignores armor and is the way into Hemorrhage."] = "Cuchillas dentadas ignora la armadura y es el camino hacia Hemorragia."
L["Hemorrhage is your main builder from here, with any weapon, and it adds to Rupture damage."] = "Hemorragia es tu principal generador de puntos de combo desde aquí, con cualquier arma, y añade daño a Desgarrar."
L["Quietus adds damage to Hemorrhage and Ghostly Strike on a low-health target, finishing mobs sooner."] = "Quietud añade daño a Hemorragia y Golpe espectral en un objetivo con poca salud, terminando con los enemigos antes."
L["Thousand Cuts is the capstone: Rupture ticks make your next Hemorrhage cheaper."] = "Mil cortes es el capstone: los pulsos de Desgarrar hacen que tu próxima Hemorragia sea más barata."
L["Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way."] = "Sube de nivel como Armas con arma de dos manos (Golpe mortal, Golpe en arco) o Furia (Encolerizar, Sed de muerte, luego Frenesí y Sed de sangre con dos armas). Protección es más lento solo pero preparado para tanquear cualquier calabozo en el camino."
L["Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them."] = "Primero Golpe heroico mejorado: el Golpe heroico es tu principal consumidor de ira, y uno más barato significa más usos."
L["Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing."] = "El Dominio táctico mejorado conserva la ira al cambiar de postura, así que Carga, Sobreponerse y los openers en Postura de Batalla no cuestan nada."
L["Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls."] = "El Control de la ira es un goteo constante de ira en cada combate; en Forever también ralentiza la pérdida de ira entre ataques."
L["Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale."] = "Desgarrar mejorado y Heridas profundas convierten tus críticos en sangrado; Heridas profundas también abre Empalamiento."
L["Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type."] = "Los Golpes en arco hacen rápidos los ataques a dos enemigos; el Maestro de armas añade crítico, penetración de armadura o ataques extra según tu tipo de arma."
L["Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings."] = "El Golpe rápido mejorado evita que Golpe rápido reinicie tu ataque: un golpe libre entre los grandes ataques de arma de dos manos."
L["Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb."] = "El Golpe mortal es el capstone y tu golpe más potente para el resto de la subida."
L["The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage."] = "Los últimos 20 puntos van a Furia: Crueldad y Cólera desenfrenada dan más crítico y más ira."
L["Enrage finishes the plan: a damage boost that is often up while you take hits."] = "Encolerizar termina el plan: un aumento de daño que suele estar activo mientras recibes golpes."
L["Cruelty first: more crit for every build, and the way into the Fury tree."] = "Primero Crueldad: más crítico para cualquier build y la entrada al árbol de Furia."
L["Unbridled Wrath means more rage from every swing, which matters most with two fast weapons."] = "La Cólera desenfrenada significa más ira de cada golpe, lo que importa más con dos armas rápidas."
L["Piercing Howl stops runners and lets you walk away from a bad pull."] = "El Alarido penetrante detiene a los que huyen y te permite alejarte de un pull malo."
L["Enrage raises your physical damage after you are hit, so it is often up while you take hits."] = "Encolerizar aumenta tu daño físico después de recibir un golpe, así que suele estar activo mientras recibes golpes."
L["Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry."] = "La Sed de muerte es un gran tiempo de reutilización para élites y rompe el miedo; también abre Frenesí."
L["Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons."] = "Especialización en doble arma: más daño de mano secundaria e ira ahora que llevas dos armas."
L["Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs."] = "La Sed de sangre es el capstone: un fuerte ataque instantáneo y un poco de velocidad de movimiento entre enemigos."
L["Gore Drinker turns your rage cooldowns into self-healing, so you rest less."] = "Bebedor de sangre convierte tus tiempos de reutilización de ira en autocuración, así que descansas menos."
L["Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."] = "Los puntos sobrantes van a Armas para Golpes heroicos más baratos, ira al cambiar de postura, Control de la ira y Heridas profundas."
L["Shield Specialization: more blocks, and on Forever each block also gives rage."] = "Especialización en escudo: más bloqueos, y en Forever cada bloqueo también da ira."
L["Improved Revenge makes Revenge, which you can use after each block, a real damage hit."] = "El Golpe de represalia mejorado hace que el Golpe de represalia, que puedes usar después de cada bloqueo, sea un golpe de daño real."
L["Last Stand is your emergency cooldown when a pull goes wrong."] = "Último recurso es tu tiempo de reutilización de emergencia cuando una atracción sale mal."
L["Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull."] = "El Vanguard te permite Cargar desde Postura defensiva: no hay danza de posturas para iniciar una atracción."
L["Concussion Blow is a stun on demand, for an interrupt or to reach a runner."] = "El Golpe concusivo es un aturdimiento a demanda, para interrumpir o alcanzar a un que huye."
L["Bastion adds damage to everything you do with a shield on; it is what makes Protection level well."] = "El Bastión añade daño a todo lo que haces con un escudo; es lo que hace que Protección levee bien."
L["Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons."] = "El Golpe de escudo es el capstone: un gran golpe que crece con tu valor de bloqueo y alta amenaza para calabozos."
L["Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons."] = "Desafío, Palmada de trueno mejorada y Muro de escudos mejorado completan el kit de tanque para calabozos."
L["The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."] = "Los últimos 10 puntos van a Armas: Golpes heroicos más baratos y Dominio táctico mejorado para cambios a Postura de Batalla."
L["Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls."] = "Sube de nivel como Escarcha (lo más seguro: ralentizaciones, congelaciones y Barrera de hielo) o Fuego (más daño, con aperturas de Piroblasto y Onda de choque). Arcano gira en torno a Explosión arcana y Poder arcano y necesita más maná entre ataques."
L["Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you."] = "Primero Canalización mejorada: los Misiles arcanos, y más tarde la Explosión arcana, continúan cuando un enemigo te golpea."
L["Arcane Concentration gives free casts now and then, and opens Arcane Meditation."] = "La Concentración arcana da lanzamientos gratuitos de vez en cuando y abre la Meditación arcana."
L["Arcane Blast is Forever's Arcane builder: each cast adds spell power for the next."] = "La Explosión arcana es el generador de Arcano de Forever: cada lanzamiento añade poder de hechizo para el siguiente."
L["Missile Barrage: Arcane Blast, Arcane Wrath, Fireball and Frostbolt can make your next Arcane Missiles faster and cheaper."] = "Lluvia de misiles: la Explosión arcana, la Cólera arcana, la Bola de fuego y el Rayo de escarcha pueden hacer tus próximos Misiles arcanos más rápidos y baratos."
L["Arcane Meditation keeps mana coming back while you cast, so you drink less."] = "La Meditación arcana mantiene el maná regenerándose mientras lanzas hechizos, así bebes menos."
L["Arcane Wrath, opened by Arcane Blast, is a nuke that grows with your maximum mana. Its point does not count toward the Arcane tiers, so the plan spends 32 points in Arcane."] = "La Cólera arcana, abierta por la Explosión arcana, es un hechizo de daño que crece con tu maná máximo. Su punto no cuenta para los niveles de Arcano, por lo que el plan gasta 32 puntos en Arcano."
L["Presence of Mind makes one spell instant: an opener, or a finisher on a runner."] = "Presencia de mente hace un hechizo instantáneo: un abridor o un rematador en alguien que huye."
L["Arcane Power is the capstone: more damage for more mana, best with Presence of Mind on a tough target."] = "El Poder arcano es el capstone: más daño a cambio de más maná, mejor con Presencia de mente en un objetivo difícil."
L["The remaining 19 points go to Frost for a quicker Frostbolt, a shorter Frost Nova cooldown, longer slows and Ice Block."] = "Los 19 puntos restantes van a Escarcha para un Rayo de escarcha más rápido, un enfriamiento más corto de Nova de escarcha, ralentizaciones más largas y Bloque de hielo."
L["Improved Fireball first: a faster Fireball is more damage every fight."] = "Primero Bola de fuego mejorada: una Bola de fuego más rápida es más daño en cada combate."
L["Ignite adds burn damage to every Fire crit."] = "Ignición añade daño de quemadura a cada crítico de Fuego."
L["Pyroblast is a big opener from range; cast it first, then Fireball."] = "El Piroblasto es un gran iniciador a distancia; lánzalo primero, luego Bola de fuego."
L["Master of Elements gives mana back on crits, so you rest less."] = "El Maestro de los elementos devuelve maná al golpear crítico, así que descansas menos."
L["Critical Mass and Blast Wave: more crits, and an area attack and daze for when two mobs reach you."] = "Masa crítica y Onda de choque: más críticos, y un ataque de área y aturdimiento para cuando dos enemigos te alcancen."
L["Fire Power raises your Fire damage for each of your Fire effects on the target: Ignite, Pyroblast's burn and the like."] = "El Poder del fuego aumenta tu daño de Fuego por cada efecto de Fuego que tengas en el objetivo: Ignición, la quemadura de Piroblasto y similares."
L["Combustion is the capstone: a crit cooldown for elites and big pulls."] = "La Combustión es el capstone: un tiempo de reutilización de críticos para élites y grandes ataques."
L["The last 20 points go to Arcane: a stronger wand for finishing mobs, then Arcane Concentration's free casts and Arcane Meditation's regen while casting."] = "Los últimos 20 puntos van a Arcano: una varita más fuerte para terminar con los enemigos, luego los lanzamientos gratuitos de la Concentración arcana y la regeneración al lanzar de la Meditación arcana."
L["Improved Frostbolt first: a faster Frostbolt is your main gain for the early levels."] = "Primero Rayo de escarcha mejorado: un Rayo de escarcha más rápido es tu principal ganancia para los niveles iniciales."
L["Ice Shards makes Frost crits hit much harder."] = "Las Esquirlas de hielo hacen que los críticos de Escarcha golpeen mucho más fuerte."
L["Improved Frost Nova and Ice Block are your escapes: freeze, step back, keep casting."] = "La Nova de escarcha mejorada y el Bloque de hielo son tus vías de escape: congela, retrocede, sigue lanzando."
L["Shatter adds a large crit chance against frozen targets: Frost Nova, then Frostbolt or Ice Lance."] = "La Fragmentación añade una gran probabilidad de crítico contra objetivos congelados: Nova de escarcha, luego Rayo de escarcha o Lanza de hielo."
L["Ice Barrier is the capstone: an absorb shield that also stops pushback while you cast."] = "La Barrera de hielo es el capstone: un escudo de absorción que también detiene el retroceso mientras lanzas hechizos."
L["Level as Affliction (instant Corruption, Siphon Life, drains) or Demonology (a tougher Voidwalker, Soul Link) for the fewest deaths. Destruction hits hardest with Conflagrate and Incinerate but needs more rest."] = "Sube de nivel como Aflicción (Corrupción instantánea, Sifón de vida, drenar) o Demonología (un Caminante del Vacío más resistente, Lazo del alma) para las menos muertes. Destrucción golpea más fuerte con Conflagrar e Incinerar, pero necesita más descanso."
L["Improved Corruption makes Corruption instant: the core of Affliction leveling."] = "La Corrupción mejorada hace que la Corrupción sea instantánea: el núcleo del leveo de Aflicción."
L["Improved Drains and Soul Harvest make Drain Life a heal and Drain Soul a mana return on kills."] = "Las Drenas mejoradas y la Cosecha de almas hacen que Drenar vida sea una curación y Drenar alma devuelva maná al matar."
L["Nightfall gives an instant Shadow Bolt now and then while your damage over time ticks."] = "Caída de la noche da un Rayo de las sombras instantáneo de vez en cuando mientras tus efectos de daño con el tiempo hacen tic."
L["Siphon Life adds another self-heal over time to the rotation."] = "El Sifón de vida añade otra curación propia con el tiempo a la rotación."
L["Shadow Mastery adds damage to every Shadow spell."] = "El Dominio de las sombras añade daño a cada hechizo de Sombras."
L["Wrack is the capstone: a strong channel that raises the damage the target takes from your other Shadow damage-over-time effects by 10%."] = "Wrack es el capstone: un hechizo canalizado potente que aumenta el daño que recibe el objetivo de tus otros efectos de daño de Sombras con el tiempo en un 10%."
L["The last 20 points go to Demonology: more Stamina, a tougher Voidwalker, quicker summons and Demonic Sacrifice."] = "Los últimos 20 puntos van a Demonología: más Aguante, un Caminante del Vacío más resistente, invocaciones más rápidas y Sacrificio demoníaco."
L["Demonic Embrace first: more Stamina means more Life Taps and fewer deaths."] = "Primero el Abrazo demoníaco: más Aguante significa más Sorbos de vida y menos muertes."
L["Improved Voidwalker makes your tank pet hold mobs better and shield you."] = "El Caminante del Vacío mejorado hace que tu mascota tanque sujete mejor a los enemigos y te proteja."
L["Soul Link shares your damage with your pet: with a Voidwalker you rarely die."] = "El Lazo del alma comparte tu daño con tu mascota: con un Caminante del Vacío raramente mueres."
L["Demonic Pact is the capstone: you keep Demonic Sacrifice's effect when you summon another demon."] = "El Pacto demoníaco es el capstone: mantienes el efecto de Sacrificio demoníaco cuando invocas otro demonio."
L["The rest goes to Affliction: an instant Corruption, stronger drains and Life Tap, and Nightfall's free Shadow Bolts."] = "El resto va a Aflicción: una Corrupción instantánea, drenajes y Sorbo de vida más fuertes, y los Rayos de las sombras gratuitos de Caída de la noche."
L["Bane first: faster Shadow Bolts and Immolates."] = "Primero Maldición: Rayos de sombras e Inmolaciones más rápidos."
L["Ruin makes Destruction crits hit much harder."] = "La Ruina hace que los críticos de Destrucción golpeen mucho más fuerte."
L["Conflagrate turns your Immolate into burst damage; open with Immolate, then Conflagrate."] = "Conflagrar convierte tu Inmolación en daño explosivo; empieza con Inmolación, luego Conflagrar."
L["Incinerate is the capstone: a strong Fire nuke, best on an Immolated target."] = "Incinerar es el capstone: un potente hechizo de Fuego, mejor en un objetivo Inmolado."
L["Level as Feral Combat: Cat Form for quick kills, Bear Form for tough pulls, and no drinking. Balance kills from range with roots and Starfire; Restoration heals any dungeon and quests slowly with Wrath."] = "Sube de nivel como Feral: Forma felina para kills rápidos, Forma de oso para pulls difíciles, sin necesidad de beber. Equilibrio mata a distancia con raíces y Fuego estelar; Restauración cura cualquier calabozo y levea lento con Cólera."
L["Improved Wrath first: a faster, cheaper Wrath is most of your early damage."] = "Primero Cólera mejorada: una Cólera más rápida y barata es la mayor parte de tu daño inicial."
L["Moonglow and Nature's Majesty: cheaper spells and more crit."] = "Resplandor lunar y Majestuosidad natural: hechizos más baratos y más críticos."
L["Improved Entangling Roots holds a mob in place while you nuke it from range."] = "Las Raíces enredadoras mejoradas inmoviliza a un enemigo mientras lo atacas desde la distancia."
L["Nature's Grace speeds up your next spell after a crit."] = "La Gracia natural acelera tu próximo hechizo después de un crítico."
L["Moonkin Form is the capstone: armor and more free casts while you nuke."] = "La Forma de búho lunar es el capstone: armadura y más lanzamientos gratuitos mientras atacas."
L["The last 20 points go to Restoration: fewer interrupted casts, Naturalist's damage, regen while casting and stronger heals."] = "Los últimos 20 puntos van a Restauración: menos interrupciones en el lanzamiento, daño del Naturalista, regeneración al lanzar y curaciones más fuertes."
L["Ferocity first: cheaper Claw, Rake and Maul in both forms."] = "Primero Ferocidad: Garra, Arañar y Aporrear más baratos en ambas formas."
L["Savage Fury and Sharpened Claws add damage and crit in Cat and Bear Form."] = "La Furia salvaje y las Garras afiladas añaden daño y crítico en Forma felina y Forma de oso."
L["Predatory Strikes adds attack power in forms; it scales with your level, not your gear."] = "Los Ataques depredadores añaden poder de ataque en las formas; escala con tu nivel, no con tu equipo."
L["Leader of the Pack adds crit for you and your group."] = "El Líder de la manada añade crítico para ti y tu grupo."
L["Berserk is the capstone: a cooldown that makes Primal Bite hit several targets."] = "El Frenesí es el capstone: un tiempo de reutilización que hace que Mordisco primigenio golpee varios objetivos."
L["The last 20 points go to Restoration: rage when you shift, Naturalist's damage, cheaper shifting and regen while casting."] = "Los últimos 20 puntos van a Restauración: ira al cambiar de forma, daño del Naturalista, cambio de forma más barato y regeneración al lanzar."
L["Nature's Focus first: your casts go through while a mob hits you."] = "Primero Enfoque natural: tus lanzamientos continúan mientras un enemigo te golpea."
L["Reflection keeps mana coming back while casting, so you rest less."] = "La Reflexión mantiene el maná regenerándose mientras lanzas, así descansas menos."
L["Swiftmend uses up a Rejuvenation or Regrowth for a big instant heal."] = "La Sanación apresurada consume un Rejuvenecimiento o Recrecimiento para una curación instantánea grande."
L["Wild Growth is the capstone: a heal over time on your whole group."] = "El Crecimiento salvaje es el capstone: una curación con el tiempo para todo tu grupo."
L["The last 20 points go to Balance so you can still kill quest mobs: a faster, cheaper Wrath, roots and more crit."] = "Los últimos 20 puntos van a Equilibrio para seguir matando enemigos de misiones: una Cólera más rápida y barata, raíces y más crítico."
L["Level as Enhancement (Flurry, Stormstrike, Maelstrom Weapon) for steady melee with few rests, or Elemental (Lightning Overload, Lava Burst) to kill from range. Restoration heals dungeons well and levels slowly alone."] = "Sube de nivel como Mejora (Frenesí, Golpe de tormenta, Arma Maelstrom) para combate cuerpo a cuerpo constante con pocos descansos, o Elemental (Sobrecarga elemental, Explosión de lava) para matar a distancia. Restauración cura bien los calabozos y levea solo lentamente."
L["Concussion first: more damage from Lightning Bolt and Earth Shock, your two main spells."] = "Primero Concusión: más daño de Relámpago y Sacudida de tierra, tus dos hechizos principales."
L["Elemental Focus makes some casts free, which is the main mana saver for the early levels."] = "El Enfoque elemental hace algunos lanzamientos gratuitos, que es el principal ahorrador de maná para los primeros niveles."
L["Lava Burst is a big Fire nuke, best after Flame Shock; Call of Flame makes it stronger."] = "La Explosión de lava es un potente hechizo de Fuego, mejor después de Sacudida de llamas; Llamada de la llama lo fortalece."
L["Lightning Overload sometimes casts a second, smaller Lightning Bolt for free."] = "La Sobrecarga elemental a veces lanza un segundo Relámpago más pequeño de forma gratuita."
L["Elemental Mastery is the capstone: for a while, quicker Lightning Bolts and Lava Bursts and no cooldown on Chain Lightning."] = "La Maestría elemental es el capstone: durante un tiempo, Relámpagos y Explosiones de lava más rápidos y sin tiempo de reutilización en Cadena de relámpagos."
L["The last 20 points go to Enhancement: more Intellect, more crit, a stronger Lightning Shield and cheaper Shocks."] = "Los últimos 20 puntos van a Mejora: más Intelecto, más crítico, un Escudo de relámpagos más fuerte y Sacudidas más baratas."
L["Thundering Strikes first: crit for spells and attacks, and the way into the tree."] = "Primero Golpes atronadores: crítico para hechizos y ataques, y la entrada al árbol."
L["Mental Dexterity turns your Intellect into attack power, so mana gear helps your melee too; it also opens Flurry."] = "La Destreza mental convierte tu Intelecto en poder de ataque, así que el equipo de maná también ayuda a tu cuerpo a cuerpo; también abre Frenesí."
L["Flurry speeds up your swings after a crit and is the core of Enhancement's damage."] = "El Frenesí acelera tus ataques después de un crítico y es el núcleo del daño de Mejora."
L["Stormstrike is an instant strike that raises the damage your next spells do."] = "El Golpe de tormenta es un golpe instantáneo que aumenta el daño de tus próximos hechizos."
L["Maelstrom Weapon makes your next Lightning Bolt faster and cheaper as you hit."] = "El Arma Maelstrom hace que tu próximo Relámpago sea más rápido y barato a medida que golpeas."
L["Rage of the Farseer is the capstone: a big attack-speed cooldown for elites and pulls."] = "La Ira del Vidente es el capstone: un gran tiempo de reutilización de velocidad de ataque para élites y ataques."
L["The last 20 points go to Elemental for stronger Shocks, cheaper casts and more crit from spells."] = "Los últimos 20 puntos van a Elemental para Sacudidas más fuertes, lanzamientos más baratos y más crítico de hechizos."
L["Tidal Focus first: cheaper heals, and more hit for your Lightning Bolts while you quest."] = "Primero Enfoque de marea: curaciones más baratas y más impacto para tus Relámpagos mientras haces misiones."
L["Totemic Focus: cheaper totems, which you drop on every pull while leveling."] = "Enfoque totémico: tótems más baratos, que colocas en cada ataque mientras subes de nivel."
L["Mindfulness keeps half your mana regeneration going while casting."] = "La Consciencia mantiene la mitad de tu regeneración de maná mientras lanzas hechizos."
L["Nature's Swiftness makes one heal instant: your emergency button."] = "La Rapidez de la naturaleza hace una curación instantánea: tu botón de emergencia."
L["Riptide is the capstone: a quick heal with a heal over time for dungeons."] = "La Marea de corriente es el capstone: una curación rápida con curación en el tiempo para calabozos."
L["The last 20 points go to Elemental, so your Lightning Bolts and Shocks still kill while you quest."] = "Los últimos 20 puntos van a Elemental, para que tus Relámpagos y Sacudidas sigan matando mientras haces misiones."
L["Feral Combat"] = "Combate Feral"
L["Restoration"] = "Restauración"
L["Level as Beast Mastery: your pet tanks and does much of the damage, so you rarely stop. Marksmanship hits harder from range with Careful Aim and Sniper Shot; Survival fights in melee with Predator's Edge and Lacerating Strikes."] = "Sube de nivel como Dominio de bestias: tu mascota tanquea y hace gran parte del daño, así que raramente te detienes. Puntería golpea más fuerte a distancia con Puntería precisa y Disparo del francotirador; Supervivencia combate en melee con Ventaja del depredador y Tiras lacerantes."
L["Deadly Aspects first: more from Aspect of the Hawk while your pet holds the mob."] = "Primero Aspectos mortíferos: más del Aspecto del halcón mientras tu mascota retiene al enemigo."
L["Unleashed Fury adds pet damage, and your pet is most of your damage."] = "La Furia desencadenada añade daño de mascota, y tu mascota es la mayor parte de tu daño."
L["Intimidation stuns through your pet: a breather when a mob turns on you."] = "La Intimidación aturde a través de tu mascota: un respiro cuando un enemigo se vuelve contra ti."
L["Bestial Wrath is the capstone: your pet's big damage cooldown."] = "La Ira bestial es el capstone: el gran tiempo de reutilización de daño de tu mascota."
L["The last 20 points go to Marksmanship: more crit, attack power from Intellect, a shorter Rapid Fire and harder ranged crits."] = "Los últimos 20 puntos van a Puntería: más crítico, poder de ataque del Intelecto, un Fuego rápido más corto y críticos a distancia más fuertes."
L["Lethal Attacks first: crit for every shot."] = "Primero Ataques letales: crítico para cada disparo."
L["Careful Aim adds attack power from your Intellect."] = "La Puntería precisa añade poder de ataque desde tu Intelecto."
L["Mortal Shots makes your ranged crits hit much harder."] = "Los Disparos mortales hacen que tus críticos a distancia golpeen mucho más fuerte."
L["Sniper Shot is the capstone: a long-range opener that hits hard."] = "El Disparo del francotirador es el capstone: un abridor de largo alcance que golpea fuerte."
L["The last 20 points go to Beast Mastery: a stronger Aspect of the Hawk and a tougher, harder-hitting pet."] = "Los últimos 20 puntos van a Dominio de bestias: un Aspecto del halcón más fuerte y una mascota más resistente y poderosa."
L["Improved Tracking first: keep tracking on for its bonus against the mobs you quest on."] = "Primero Rastreo mejorado: mantén el Rastreo activo por su bonificación contra los enemigos que buscas en la misión."
L["Deterrence is a dodge and parry cooldown for melee fights that go wrong."] = "La Disuasión es un tiempo de reutilización de esquiva y parada para los combates cuerpo a cuerpo que salen mal."
L["Lightning Reflexes adds Agility: more attack power, crit and dodge."] = "Los Reflejos de rayo añaden Agilidad: más poder de ataque, crítico y esquiva."
L["Lacerating Strikes is the capstone: Mongoose Bite also makes the target bleed."] = "Los Tiras lacerantes son el capstone: la Mordedura de mangosta también hace sangrar al objetivo."
L["Level as Shadow (Spirit Tap, Mind Flay, Shadowform) for the fastest kills and least drinking. Discipline levels with Smite and Penance behind a strong shield; Holy is the dungeon healer and slower alone."] = "Sube de nivel como Sombra (Absorción espiritual, Desgarro mental, Forma sombría) para las matanzas más rápidas y el menor consumo. Disciplina levea con Castigo y Penitencia detrás de un escudo fuerte; Sagrado es el sanador de calabozo y más lento solo."
L["Power in Light first: more Smite damage, your main attack as Discipline, on targets with your Holy Fire or Shadow Word: Pain."] = "Primero Poder en la Luz: más daño de Castigo, tu ataque principal como Disciplina, en objetivos con tu Fuego sagrado o Palabra sombría: Dolor."
L["Improved Power Word: Shield: a bigger shield is fewer interrupted casts and less healing."] = "Mejora de Palabra de poder: Escudo: un escudo más grande significa menos interrupciones y menos curación."
L["Penance is a channelled burst of Holy damage or healing: use it on every mob."] = "La Penitencia es una ráfaga canalizada de daño sagrado o curación: úsala en cada enemigo."
L["Power Infusion is the capstone: a damage and healing cooldown for you or an ally."] = "La Infusión de poder es el capstone: un tiempo de reutilización de daño y curación para ti o un aliado."
L["The last 20 points go to Shadow: Spirit Tap's regen after kills, a longer Shadow Word: Pain, more Shadow hit, Mind Flay and a quicker Mind Blast."] = "Los últimos 20 puntos van a Sombra: la regeneración de Absorción espiritual tras las matanzas, una Palabra sombría: Dolor más larga, más impacto de Sombra, Desgarro mental y un Explosión mental más rápido."
L["Holy Specialization first: more crits on Smite and on your heals."] = "Primero Especialización sagrada: más críticos en Castigo y en tus curaciones."
L["Divine Fury speeds up Smite, Holy Fire and your big heals."] = "La Furia divina acelera Castigo, Fuego sagrado y tus grandes curaciones."
L["Spiritual Guidance adds 25% of your Spirit to your healing but only 8% to your damage: Spirit gear helps your heals most."] = "Guía espiritual suma a tu sanación el 25% de tu Espíritu, pero a tu daño solo el 8%: el equipo de Espíritu ayuda más a tus sanaciones."
L["Prayer of Mending is the capstone: a heal that jumps between your group as they take damage."] = "La Oración de curación es el capstone: una curación que salta entre tu grupo a medida que sufre daño."
L["The last 20 points go to Discipline: a stronger wand, a bigger Power Word: Shield, Meditation's regen while casting and more Intellect."] = "Los últimos 20 puntos van a Disciplina: una varita más fuerte, una Palabra de poder: Escudo más grande, regeneración de Meditación al lanzar y más Intelecto."
L["Mental Strength comes last: on Forever its points do not count toward the Discipline tiers."] = "La Fortaleza mental va al final: en Forever, sus puntos no cuentan para los niveles de Disciplina."
L["Spirit Tap first: after each kill your regen jumps, so you drink far less."] = "Primero Absorción espiritual: después de cada matanza tu regeneración sube, así bebes mucho menos."
L["Mind Flay is your main damage and slow from here; Improved Mind Flay makes it hit harder."] = "El Desgarro mental es tu principal daño y ralentización desde aquí; el Desgarro mental mejorado lo hace golpear más fuerte."
L["Vampiric Embrace heals you from your Shadow damage."] = "El Abrazo vampírico te cura con tu daño de Sombras."
L["Shadowform is the capstone: more Shadow damage and less physical damage taken."] = "La Forma sombría es el capstone: más daño de Sombras y menos daño físico recibido."
L["ForeverDB through level 30, Polestar after"] = "ForeverDB hasta el nivel 30, Polestar después"
L["Polestar, with ForeverDB's builds to level 20"] = "Polestar, con los builds de ForeverDB hasta el nivel 20"
L["Polestar, with ForeverDB's talent data"] = "Polestar, con los datos de talentos de ForeverDB"
L["ForeverDB"] = "ForeverDB"
L["ForeverDB's leveling builds, adapted to level 30"] = "Builds de ForeverDB para subir de nivel, adaptados al nivel 30"

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Ceder la guía a Shortest Path Forever"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "La flecha, la ruta y el trayecto de Shortest Path Forever te llevan a cada objetivo. La flecha de Polestar, las líneas de ruta, los pasos del trayecto, el botón de viaje, los avisos de transporte, los clics en el mapa y /way se apartan; la ventana de la guía y los marcadores del mapa se quedan. Desactivado: guía Polestar, y solo se aparta mientras dure un trayecto que iniciaste en Shortest Path Forever."

-- Core/Import.lua
L["Imported"] = "Importadas"
L["This import string is damaged or incomplete. Copy the whole string again."] = "Este texto de importación está dañado o incompleto. Vuelve a copiarlo completo."
L["This import string needs a newer Polestar."] = "Este texto de importación necesita un Polestar más reciente."
L["This import string holds no guide."] = "Este texto de importación no contiene ninguna guía."
L["Its guide id %s must start with its author's own id, as in yendi/cozy-sleeping-bag."] = "El id de su guía, %s, debe empezar con el id propio de su autor, como en yendi/cozy-sleeping-bag."
L["Guides under %s/ come from the community addon %s, which is installed."] = "Las guías bajo %s/ vienen del AddOn de la comunidad %s, que está instalado."
L["Its guide has %d steps; an import string holds %d at most. A bigger guide comes as a community addon."] = "Su guía tiene %d pasos; un texto de importación admite %d como máximo. Una guía más grande llega como AddOn de la comunidad."
L["It leads on to %s, which is neither one of Polestar's guides nor an imported one: import that guide first."] = "Continúa en %s, que no es una guía de Polestar ni una importada: importa primero esa guía."
L["This import string holds a field Polestar does not read (%s). It may need a newer Polestar."] = "Este texto de importación contiene un campo que Polestar no lee (%s). Tal vez necesite un Polestar más reciente."
L["Paste an import string."] = "Pega un texto de importación."
L["This import string is too long: Polestar reads up to %d characters."] = "Este texto de importación es demasiado largo: Polestar lee hasta %d caracteres."
L["This is not a Polestar import string."] = "Esto no es un texto de importación de Polestar."
L["This game client cannot read import strings."] = "Este cliente del juego no puede leer textos de importación."
L["This import string holds a text longer than Polestar reads (%s): %d characters at most."] = "Este texto de importación contiene un texto más largo de lo que Polestar lee (%s): %d caracteres como máximo."
L["This import string holds too much: Polestar reads up to %d KB of guide data."] = "Este texto de importación contiene demasiado: Polestar lee hasta %d KB de datos de guía."
L["Its guide has %d goals in step %d; an import string holds %d per step at most."] = "Su guía tiene %d objetivos en el paso %d; un texto de importación admite %d por paso como máximo."
L["Its guide has %d candidates in a goal; an import string holds %d per goal at most."] = "Su guía tiene %d candidatos en un objetivo; un texto de importación admite %d por objetivo como máximo."
L["Its guide has more than one direct turn-in for quest %d in step %d."] = "Su guía tiene más de una entrega directa para la misión %d en el paso %d."
L["Its guide has a candidate coordinate outside 0-100."] = "Su guía tiene una coordenada de candidato fuera de 0-100."
L["Its guide has a spot coordinate outside 0-100."] = "Su guía tiene una coordenada de lugar fuera de 0-100."
L["Its guide has a map frame with missing fields."] = "Su guía tiene un marco de mapa con campos faltantes."
L["Its guide has a degenerate map frame (zero extent)."] = "Su guía tiene un marco de mapa degenerado (extensión cero)."
L["Its guide has a map frame with out-of-range coordinates."] = "Su guía tiene un marco de mapa con coordenadas fuera de rango."
L["No imported guides to remove."] = "No hay guías importadas que quitar."
L["Removed %d imported guide(s)."] = "Se quitaron %d guía(s) importada(s)."
L["Usage: /polestar import delete <guide-id>"] = "Uso: /polestar import delete <guide-id>"
L["Removed imported guide %s."] = "Se quitó la guía importada %s."
L["No imported guide with id %s."] = "No hay ninguna guía importada con el ID %s."
L["Open the Import page; import clear / import delete <id>: remove imports"] = "Abrir la página Importar; import clear / import delete <id>: quitar importaciones"
L["Its guide has %d entries in %s; an import string holds %d there at most."] = "Su guía tiene %d entradas en %s; un texto de importación admite %d allí como máximo."

