-- L["Shortest Path Forever is guiding. Turn off \"Guide with Shortest Path Forever when it's installed\" (Options, Integrations) to use Polestar's arrow."] = "Shortest Path Forever está guiando. Desactiva \"Guiar con Shortest Path Forever si está instalado\" (Opciones, Integraciones) para usar la flecha de Polestar."
-- L["Guide with Shortest Path Forever when it's installed"] = "Guiar con Shortest Path Forever si está instalado"
-- L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay."] = "La flecha, la ruta y el trayecto de Shortest Path Forever te llevan a cada objetivo. La flecha de Polestar, las líneas de ruta, los pasos del trayecto, el botón de viaje, los avisos de transporte, los clics en el mapa y /way se apartan; la ventana de la guía y los marcadores del mapa se quedan."
-- L["Browsing the guide needs a gamepad: turn it on in the game's options and plug one in."] = "Para recorrer la guía se necesita un control: actívalo en las opciones del juego y conecta uno."
-- L["Follow a talent plan for your class and spec (/pole talents). Paladin only for now."] = "Sigue un plan de talentos para tu clase y especialización (/pole talents). Por ahora solo Paladín."
-- L["Talent plans cover the Paladin for now. More classes will follow."] = "Por ahora los planes de talentos cubren al Paladín. Vendrán más clases."
-- L["The game's own font (the default), Inter, or EllesmereUI's."] = "La fuente propia del juego (predeterminada), Inter o la de EllesmereUI."
-- L["Your report"] = "Tu informe"
-- L["Select report"] = "Seleccionar informe"
-- L["Copy your report with Ctrl+C (Cmd+C on a Mac), switch to Discord and paste it in the Polestar server. Not in it yet? Get the invite once and open it in your browser."] = "Copia tu informe con Ctrl+C (Cmd+C en Mac), cambia a Discord y pégalo en el servidor de Polestar. ¿Aún no estás? Consigue la invitación una vez y ábrela en tu navegador."
-- L["Next boat in about %s"] = "Próximo barco en unos %s"
-- L["Next zeppelin in about %s"] = "Próximo zepelín en unos %s"
-- L["Next tram in about %s"] = "Próximo tranvía en unos %s"
-- L["Next lift in about %s"] = "Próximo ascensor en unos %s"
-- L["leaves in about %s"] = "sale en unos %s"
-- L["Scale of the quest item, Hearthstone and target buttons. Drag one to move them all."] = "Escala de los botones de objeto de misión, piedra de hogar y objetivo. Arrastra uno para moverlos todos."
-- L["Route"] = "Ruta"
-- L["Open the Import page: guides shared as text"] = "Abrir la página Importar: guías compartidas como texto"
-- L["WoW Forever"] = "WoW Forever"
-- L["Take %s"] = "Toma %s"
-- L["Take the lift"] = "Toma el ascensor"
-- L["Planned in a simulator and played to the end in tests, but nobody has followed them through the live game yet. Skip a wrong step with %s and tell us on Discord."] = "Planeadas en un simulador y jugadas hasta el final en pruebas, pero nadie las ha seguido aún en el juego real. Omite un paso equivocado con %s y avísanos en Discord."
-- L["Feedback, bug reports and news"] = "Comentarios, informes de errores y novedades"
-- L["Guides made by other players for Polestar, not our own routes: each community addon is installed like any other addon. Its guides appear in %s under Community guides, credited to their author, who supports them. More in Options > Community guides."] = "Guías hechas por otros jugadores para Polestar, no nuestras propias rutas: cada AddOn de la comunidad se instala como cualquier otro AddOn. Sus guías aparecen en %s, en Guías de la comunidad, con el nombre de su autor, que las mantiene. Más en Opciones > Guías de la comunidad."
-- L["The step you are on."] = "El paso en el que estás."
-- L["Points the way."] = "Te señala el camino."
-- L["The map marks each place."] = "El mapa marca cada lugar."
-- L["How the arrow walks you. You can change it any time in Options."] = "Cómo te guía la flecha. Puedes cambiarlo cuando quieras en Opciones."
-- L["Sessions stored"] = "Sesiones guardadas"
-- L["Kept in SavedVariables until imported with the toolchain."] = "Se guardan en SavedVariables hasta importarlas con las herramientas."
-- L["Events this session"] = "Eventos de esta sesión"
-- L["Character"] = "Personaje"
-- L["Session"] = "Sesión"
-- L["Counts and the current session in chat."] = "Conteos y la sesión actual en el chat."
-- L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance is sent in by the Image of Archmage Modera."] = "Abre la puerta del camino de la Horda hacia la Ciudad de Dalaran; una llave la abre para el grupo. A la Alianza la envía dentro la Imagen de la archimaga Modera."
-- L["Accepted a resurrection."] = "Aceptaste una resurrección."
-- L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator)."] = "El objeto que usa el paso actual, o un objeto de misión que recoge, brilla en tus bolsas (y en Baganator)."
-- L["Sells Poor-quality items when a merchant opens and prints the total. Never sells anything else."] = "Vende los objetos de calidad Pobre al abrir un mercader y muestra el total. Nunca vende nada más."
-- L["Picks the only option of NPCs without quests. Hold Shift to read it."] = "Elige la única opción de los PNJ sin misiones. Mantén presionado Mayús para leerla."
-- L["Earlier quests of this chain are not listed."] = "Las misiones anteriores de esta cadena no aparecen."
-- L["Small conveniences: travel, invitations, merchants and trackers."] = "Pequeñas comodidades: viajes, invitaciones, mercaderes y rastreadores."
-- L["Party members who run Polestar see your counts under their quest goals. Nothing goes to chat."] = "Los miembros del grupo que usan Polestar ven tu progreso bajo los objetivos de sus misiones. No se envía nada al chat."
-- L["Their counts under your quest goals, and who lacks a quest you took."] = "Muestra su progreso bajo los objetivos de tus misiones e indica quién no tiene una misión que tú has aceptado."
-- L["Each Polestar member's level, step and what they still need of yours; click a name to point the arrow at them. /polestar party shows or hides it."] = "El nivel y el paso de cada miembro con Polestar, y lo que aún le falta del tuyo; haz clic en un nombre para que la flecha apunte a él. /polestar party lo muestra u oculta."
-- L["%s from another version"] = "%s de otra versión"
-- L["Polestar %s is installed incompletely: %s. Close the game, delete every Polestar folder in Interface/AddOns and unzip the latest Polestar zip there (CurseForge or GitHub Releases, not \"Source code\")."] = "Polestar %s está instalado de forma incompleta: %s. Cierra el juego, borra todas las carpetas de Polestar en Interface/AddOns y descomprime ahí el zip más reciente de Polestar (CurseForge o GitHub Releases, no \"Source code\")."
-- L["Objective areas"] = "Áreas de objetivos"
-- L["Shade the area each group of mobs or objects spreads over on the world map."] = "Sombrea en el mapa del mundo el área que ocupa cada grupo de monstruos u objetos."
-- L["The guide window hides in dungeons and battlegrounds. Type /polestar to show it here, or change it in Options > Guide > Window."] = "La ventana de la guía se oculta en calabozos y campos de batalla. Escribe /polestar para mostrarla aquí, o cámbialo en Opciones > Guía > Ventana."
-- L["Celebrating the supporters and contributors behind Polestar."] = "Un homenaje a quienes apoyan y contribuyen a Polestar."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. /polestar or the key binding opens it there until you leave."] = "Qué hacen la ventana, sus botones y sus alertas en calabozos, bandas, campos de batalla y arenas. /polestar o el atajo de teclado la abre allí hasta que salgas."
-- L["Also a quest ready to hand in whose NPC stands right here, when the guide hands it in later."] = "También una misión lista para entregar cuyo PNJ está justo aquí, cuando la guía la entrega más adelante."
-- L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Your party sees the icons; in a raid only the leader and assistants can set them."] = "El botón de objetivo y la tecla del paso ponen un icono de banda en el monstruo y en el PNJ que seleccionan; fuera de combate, una pulsación que no encuentra ninguno quita tu objetivo. Tu grupo ve los iconos; en una banda solo el líder y los asistentes pueden ponerlos."
-- L["The last guides you loaded."] = "Las últimas guías que cargaste."
-- L["The way to the goal on the world map and the minimap: dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "El camino al objetivo en el mapa del mundo y el minimapa: puntos donde caminas, líneas donde vuelas, navegas o viajas, y los tramos siguientes más tenues. Dibujado como lo dibuja Shortest Path Forever de Cillian Berragan."
-- L["Three choices to start with. Everything else is in %s."] = "Tres opciones para empezar. Todo lo demás está en %s."
-- L["How the route lines are drawn: Polestar's dots, or sparkles that drift along the way to the goal."] = "Cómo se dibujan las líneas de ruta: con los puntos de Polestar o con destellos que se desplazan por el camino hacia el objetivo."
-- L["The first walk of %s"] = "La primera caminata de %s"
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and a floating Polestar button can be turned on in Options."] = "Las carpetas del explorador se pliegan, una pestaña cerrada vuelve con Reabrir, la ruta puede verse como línea, puntos o destellos en el mapa y el minimapa, y se puede activar un botón flotante de Polestar en Opciones."
-- L["Found something off?"] = "¿Encontraste algo raro?"
-- L["Type %s right where it happens."] = "Escribe %s justo donde ocurre."
-- L["Guide menu and minimap"] = "Menú de guías y minimapa"
-- L["Quests asked for before the game offers them, wrong spots, dungeon pick-ups, guides opened part-way, the arrow while you're a ghost, and lots more."] = "Misiones pedidas antes de que el juego las ofrezca, lugares equivocados, misiones de calabozo, guías abiertas a medias, la flecha mientras eres fantasma, y mucho más."
-- L["Grinding steps point at where the mob is found, and on a step with several camps the arrow moves on from one you've emptied. The Target button shows who it targets, the While you're here mobs included."] = "Los pasos de farmeo apuntan a donde se encuentra el monstruo, y en un paso con varios campamentos la flecha pasa al siguiente cuando vacías uno. El botón de objetivo muestra a quién selecciona, incluidos los monstruos de Mientras estás aquí."
-- L["Every leveling guide was gone over again, and 40-60 reworked for both factions with more quests and shorter grinds. Quests new in Forever carry a small ∞ mark. If the guide you had open doesn't match where you are, open the guide list and pick the guide under %s. Your quest log carries over."] = "Se volvieron a revisar todas las guías de subida de nivel, y la 40-60 se rehízo para ambas facciones con más misiones y menos farmeo. Las misiones nuevas en Forever llevan una pequeña marca ∞. Si la guía que tenías abierta no coincide con dónde estás, abre la lista de guías y elige la guía bajo %s. Tu registro de misiones se conserva."
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and the minimap button and a floating Polestar button can be turned on in Options."] = "Las carpetas del explorador se pliegan, una pestaña cerrada vuelve con Reabrir, la ruta puede verse como línea, puntos o destellos en el mapa y el minimapa, y el botón del minimapa y un botón flotante de Polestar se pueden activar en Opciones."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route."] = "Las guías de subida de nivel te llevan por este calabozo donde tienen pasos para ello. Desactivado: siguen la ruta en solitario."
-- L["With Transparent, a shade with no edge behind the text, so it reads over bright ground. Off: the outlined text alone on the world."] = "Con Transparente, una sombra sin borde detrás del texto, para que se lea sobre terreno claro. Desactivado: solo el texto con contorno sobre el mundo."
-- L["The route's line, dots or sparkles on the minimap, and the gaps between the dots; the world map keeps its own. Right-click to reset."] = "La línea, los puntos o los destellos de la ruta en el minimapa, y los espacios entre los puntos; el mapa del mundo conserva los suyos. Clic derecho para restablecer."
-- L["Behind: %s (%d) at step %d, you'll be %s; grind ~%s first"] = "Vas con atraso: %s (%d) en el paso %d, serás nivel %s; farmea ~%s antes"
-- L["Behind: %s (%d) at step %d, you'll be %s; reach %d first"] = "Vas con atraso: %s (%d) en el paso %d, serás nivel %s; llega primero al nivel %d"
-- L["1 bar"] = "1 barra"
-- L["%d bars"] = "%d barras"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; grind ~%s first"] = "Vas al ritmo, pero %s (%d) en el paso %d es difícil: serás nivel %s; farmea ~%s antes"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; reach %d first"] = "Vas al ritmo, pero %s (%d) en el paso %d es difícil: serás nivel %s; llega al %d antes"
-- L["Hide the guide window"] = "Ocultar la ventana de la guía"
-- L["A Polestar button on the edge of the minimap. Click to show or hide the guide, right-click for settings, drag to move it."] = "Un botón de Polestar en el borde del minimapa. Haz clic para mostrar u ocultar la guía, clic derecho para los ajustes, arrastra para moverlo."
-- L["Click the minimap button or press %s to show it."] = "Haz clic en el botón del minimapa o pulsa %s para mostrarla."
-- L["Click the minimap button to show it."] = "Haz clic en el botón del minimapa para mostrarla."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. The minimap button, the key binding or /polestar opens it there until you leave."] = "Qué hacen la ventana, sus botones y avisos en calabozos, bandas, campos de batalla y arenas. El botón del minimapa, la tecla asignada o /polestar la abren allí hasta que salgas."
-- L["A small Polestar button you can put anywhere on the screen. Click to show or hide the guide, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Un pequeño botón de Polestar que puedes poner en cualquier parte de la pantalla. Haz clic para mostrar u ocultar la guía, clic derecho para un menú, arrastra para moverlo. Se oculta con la ventana en combate y en calabozos cuando están en Ocultar."
-- L["Click: show or hide the guide"] = "Clic: mostrar u ocultar la guía"
-- L["Show window"] = "Mostrar ventana"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Qué tan cerca debe estar su zona de aparición para que se muestre una sugerencia. Desaparece cuando te alejas un poco más."
-- L["Appearance"] = "Apariencia"
-- L["Points to the current goal. Its look and colours are under Appearance, Arrow."] = "Apunta al objetivo actual. Su aspecto y sus colores están en Apariencia, Flecha."
-- L["Colour & type"] = "Color y tipografía"
-- L["Colours, type, window frames and the arrow. Everything repaints as you change it; right-click a setting to reset it."] = "Colores, tipografía, marcos de ventana y la flecha. Todo se vuelve a pintar al cambiarlo; haz clic derecho en un ajuste para restablecerlo."
-- L["How deep the night runs. Dusk is the default, Night the darkest, Graphite a neutral grey; EllesmereUI takes its panel colour and accent."] = "Qué tan profunda es la noche. Crepúsculo es el predeterminado, Noche el más oscuro, Grafito un gris neutro; EllesmereUI toma su color de panel y su acento."
-- L["Type & motion"] = "Tipografía y movimiento"
-- L["Frame"] = "Marco"
-- L["The whole guide window, text included. The background's own opacity is under Colour & type."] = "Toda la ventana de la guía, texto incluido. La opacidad propia del fondo está en Color y tipografía."
-- L["Map icons"] = "Iconos del mapa"
-- L["Polestar's marks on the minimap; the world map keeps its own. A mark over your arrow fades so the arrow shows through it. Right-click to reset."] = "Las marcas de Polestar en el minimapa; el mapa del mundo conserva las suyas. Una marca sobre tu flecha se atenúa para que la flecha se vea a través. Clic derecho para restablecer."
-- L["Sparkle"] = "Destellos"
-- L["Subtle"] = "Sutil"
-- L["Dazzling"] = "Deslumbrante"
-- L["Route line style"] = "Estilo de las líneas de ruta"
-- L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. Right-click to reset."] = "Los colores de ruta tiñen cada tramo según cómo lo recorres. Cian, magenta y blanco se distinguen de los puntos amarillos de hierbas y minerales del minimapa y de sus marcas doradas de misión. Clic derecho para restablecer."
-- L["How thick the solid line is on the world map; the minimap's follows its size. Right-click to reset."] = "Qué tan gruesa es la línea continua en el mapa del mundo; la del minimapa sigue su tamaño. Clic derecho para restablecer."
-- L["Button size"] = "Tamaño de botones"
-- L["Target name position"] = "Posición del nombre del objetivo"
-- L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all."] = "Escala de los botones de objeto de misión, piedra de hogar, objetivo y raro. Arrastra uno para moverlos todos."
-- L["Reset to default"] = "Restablecer valor predeterminado"
-- L["Accent colour"] = "Color de acento"
