-- L["The arrow as it closes on the target, and the ring when you arrive. Right-click to go back to jade."] = "La flecha al acercarse al objetivo, y el anillo al llegar. Clic derecho para volver a jade."
-- L["Class quest chime"] = "Timbre de misión de clase"
-- L["A short chime the first time a class quest chain's card shows. Off while the game's sound effects are off."] = "Un timbre breve la primera vez que aparece la tarjeta de una cadena de misiones de clase. Desactivado mientras los efectos de sonido del juego estén desactivados."
-- L["Minimap icon size"] = "Tamaño de los iconos del minimapa"
-- L["Button in the game menu"] = "Botón en el menú del juego"
-- L["Keep the bar shown"] = "Mantener la barra visible"
-- L["How bright each sparkle and its glow are."] = "Cuánto brillan cada destello y su resplandor."
-- L["How close together the sparkles sit, the same at any zoom."] = "Qué tan juntos están los destellos, igual con cualquier zoom."
-- L["Flow toward goal"] = "Flujo hacia el objetivo"
-- L["Most sparkles shown"] = "Máximo de destellos mostrados"
-- L["Line thickness"] = "Grosor de la línea"
-- L["How strongly the route shows on the minimap, line, dots or sparkles; the world map keeps its own. Right-click to reset."] = "Qué tan visible es la ruta en el minimapa, con línea, puntos o destellos; el mapa del mundo conserva la suya. Clic derecho para restablecer."
-- L["The route's line, dots or sparkles on the minimap, each style its own size; the world map keeps its own. Right-click to reset."] = "La línea, los puntos o los destellos de la ruta en el minimapa, cada estilo con su propio tamaño; el mapa del mundo conserva el suyo. Clic derecho para restablecer."
-- L["Dungeons are turned off (Options > Discovery > Dungeons)."] = "Los calabozos están desactivados (Opciones > Descubrimiento > Calabozos)."
-- L["Comparison"] = "Comparación"
-- L["Rares & travel"] = "Raros y viajes"
-- L["Instance limits"] = "Límites de estancias"
-- L["Learn new spells"] = "Aprender hechizos nuevos"
-- L["Learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Aprende cada hechizo que ofrece un instructor de clase y que puedas pagar, y muestra el total. No toca a los instructores de profesiones. Mantén presionado Mayús para omitirlo."
-- L["Loot and merchants"] = "Botín y mercaderes"
-- L["The XP tracker is off (Options > Quality of Life > Trackers)."] = "El rastreador de PE está desactivado (Opciones > Calidad de vida > Rastreadores)."
-- L["Tooltips and quest log"] = "Descripciones y registro de misiones"
-- L["History"] = "Historial"
-- L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once every half hour, never in combat or instances."] = "Cuando %s aparece a la vista, una tarjeta lo avisa y el botón de raro lo selecciona y lo saluda. Como máximo una vez cada media hora, nunca en combate ni en estancias."
-- L["The Dungeons section is turned off. Turn it on under Options > Discovery > Dungeons."] = "La sección Calabozos está desactivada. Actívala en Opciones > Descubrimiento > Calabozos."
-- L["Polestar's own look (the default), Halo (no frame, a soft dark veil, Fira Sans), Hearth (warm game colours), or the game's own art: WoW Forever, Blizzard and Classic. Style, compact mode and the colours you pick work in each."] = "El aspecto propio de Polestar (predeterminado), Halo (sin marco, un velo oscuro suave, Fira Sans), Hogar (los colores cálidos del juego) o el arte propio del juego: WoW Forever, Blizzard y Classic. El estilo, el modo compacto y los colores que elijas funcionan en cada uno."
-- L["Tirisfal Glades"] = "Claros de Tirisfal"
-- L["Garren's Haunt"] = "Guarida de Garren"
-- L["Collect Doom Weed"] = "Consigue hierba de la perdición"
-- L["381 yd"] = "381 yd"
-- L["Dungeons and battlegrounds"] = "Calabozos y campos de batalla"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Qué tan cerca debe estar su zona de aparición para que se muestre una sugerencia. Desaparece cuando te alejas un poco más."
-- L["Characters is turned off. Turn it on under Options > Discovery > Characters."] = "Personajes está desactivado. Actívalo en Opciones > Descubrimiento > Personajes."
-- L["Dungeon heads-ups are off. Turn them back on under Options > Discovery > Dungeons."] = "Los avisos de calabozos están desactivados. Vuelve a activarlos en Opciones > Descubrimiento > Calabozos."
-- L["Colour & type"] = "Color y tipografía"
-- L["Manual check-offs and skips, current guide."] = "Marcas manuales y pasos omitidos, guía actual."
-- L["Show window"] = "Mostrar ventana"
-- L["Train all button"] = "Botón “Entrenar todo”"
-- L["Adds a Train All button to the trainer window to learn all available skills."] = "Agrega un botón “Entrenar todo” a la ventana del instructor para aprender todas las habilidades disponibles."
-- L["Auto-learn new spells"] = "Aprender hechizos nuevos automáticamente"
-- L["Automatically learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Aprende automáticamente cada hechizo que ofrece un instructor de clase y que puedas pagar, y muestra el total en el chat. Los instructores de profesión no se tocan. Mantén presionado Mayús para omitirlo."
-- L["Train All"] = "Entrenar todo"
-- L["Train %d skill for %s"] = "Entrenar %d habilidad por %s"
-- L["Train %d skills for %s"] = "Entrenar %d habilidades por %s"
-- L["Learned %d spell for %s."] = "Aprendiste %d hechizo por %s."
-- L["Learned %d spells for %s."] = "Aprendiste %d hechizos por %s."
-- L["Not enough money for %d more (%s)."] = "No tienes suficiente dinero para %d más (%s)."
-- L["Taking %s closes %s for good."] = "Aceptar %s bloquea %s para siempre."
-- L["A level-up card lists what to train; %s learns it (thanks RikyZ90); %s updates your bars."] = "Al subir de nivel, una tarjeta muestra qué entrenar; %s lo entrena todo (gracias, RikyZ90); %s pone los rangos nuevos en tus barras."
-- L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Todos los ajustes de Polestar vuelven a su valor predeterminado. Tus guías y tu progreso se conservan."
-- L["The target button and the step key ping the mob they target, so your group sees it behind rocks and buildings. Never in a raid unless you lead or assist. The rare buttons always ping."] = "El botón de objetivo y la tecla de paso marcan con un ping al monstruo que seleccionan, para que tu grupo lo vea detrás de rocas y edificios. Nunca en una banda salvo que seas líder o asistente. Los botones de raro siempre hacen ping."
-- L["Show the welcome again"] = "Mostrar la bienvenida otra vez"
-- L["Make it yours"] = "Hazlo tuyo"
-- L["Every style keeps you out of the other faction's towns and away from zones far above your level."] = "Todos los estilos te mantienen fuera de las ciudades de la otra facción y lejos de zonas muy arriba de tu nivel."
-- L["Skip keeps these as they are."] = "Omitir los deja como están."
-- L["How the arrow walks you. Change it any time in Options."] = "Cómo te hace caminar la flecha. Cámbialo cuando quieras en Opciones."
-- L["A few choices to start with. Everything else is in %s."] = "Algunas opciones para empezar. Todo lo demás está en %s."
-- L["How the way to your goal shows on the world map and the minimap. The line is the easiest to follow; sparkles show as dots while Reduce motion is on."] = "Cómo se muestra el camino a tu objetivo en el mapa del mundo y el minimapa. La línea es la más fácil de seguir; los destellos se muestran como puntos mientras Reducir movimiento está activado."
-- L["%s, %s or %s on map and minimap: set on the Welcome page or in Options."] = "%s, %s o %s en el mapa y el minimapa: elígelo en la bienvenida o en Opciones."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route. More dungeons join this list as they are added to the guides' route."] = "Las guías de subida de nivel te llevan por este calabozo donde tienen pasos para ello. Desactivado: siguen la ruta en solitario. Más calabozos se agregan a esta lista conforme entran en la ruta de las guías."
-- L["Preview"] = "Vista previa"
-- L["Brill"] = "Brill"
-- L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Todos los ajustes de Polestar vuelven a su valor predeterminado. Tus guías y tu progreso se conservan."
